function task(x){const pct=taskProgress(x),sub=(x.subtasks||[]),over=x.deadline&&x.deadline<today()&&x.status!=='done',dep=x.dependsOn?S.tasks.find(t=>t.id===x.dependsOn):null,blocked=dep&&dep.status!=='done';return'<div class="task-item task-rich '+(x.status==='done'?'task-complete':'')+' '+(blocked?'task-blocked':'')+'"><button class="check '+(x.status==='done'?'done':'')+'" data-act="toggle" data-id="'+x.id+'">'+(x.status==='done'?'✓':'')+'</button><div class="item-main"><div class="task-title-row"><div class="item-title '+(x.status==='done'?'done':'')+'">'+esc(x.title)+'</div><span class="pill task-status '+(x.status||'planned')+'">'+esc(x.status||'planned')+'</span>'+(blocked?'<span class="pill red">BLOCKED</span>':'')+(x.googleTaskSync?'<span class="pill google-pill">G Tasks</span>':'')+(x.googleCalendarSync?'<span class="pill google-pill">G Cal</span>':'')+'</div><div class="item-meta"><span>'+cat(x.category)+'</span><span>• '+mins(x.estimate)+'</span>'+(x.startTime?'<span>• '+esc(x.startTime)+'</span>':'')+(x.deadline?'<span class="'+(over?'overdue-text':'')+'">• deadline '+fmt(x.deadline,{day:'numeric',month:'short'})+'</span>':'')+(x.goalId?'<span>• '+esc(goal(x.goalId))+'</span>':'')+(x.projectId&&S.projects.find(p=>p.id===x.projectId)?'<span>• '+esc(S.projects.find(p=>p.id===x.projectId).title)+'</span>':'')+(x.studyTopicId&&S.studyTopics.find(t=>t.id===x.studyTopicId)?'<span>• '+esc(S.studyTopics.find(t=>t.id===x.studyTopicId).title)+'</span>':'')+(dep?'<span>• depends on '+esc(dep.title)+'</span>':'')+'<span class="pill '+(x.priority==='high'?'red':x.priority==='medium'?'orange':'')+'">'+x.priority+'</span>'+(x.recurrence&&x.recurrence!=='none'?'<span class="pill blue">↻ '+x.recurrence+'</span>':'')+'<span class="xp-pop">+'+taskXP(x)+' XP</span></div>'+(sub.length?'<div class="task-subtasks">'+sub.map((s,i)=>'<button class="subtask-chip '+(s.done?'done':'')+'" data-act="toggleSubtask" data-id="'+x.id+'" data-index="'+i+'"><span>'+(s.done?'✓':'○')+'</span>'+esc(s.title)+'</button>').join('')+'</div><div class="task-subprogress">'+prog(pct)+'<small>'+sub.filter(s=>s.done).length+'/'+sub.length+' subtask</small></div>':'')+((x.tags||[]).length?'<div class="task-tags">'+x.tags.map(t=>'<span>#'+esc(t)+'</span>').join('')+'</div>':'')+'</div><div class="task-actions">'+(x.status!=='done'?'<button class="mini-btn task-start" data-act="startTaskTimer" data-id="'+x.id+'" '+(blocked?'disabled title="Selesaikan dependency dahulu"':'')+'>▶ Start</button>':'')+'<button class="mini-btn" data-act="editTask" data-id="'+x.id+'">Edit</button></div></div>'}
function weekday(d=today()){return new Date(d+'T12:00:00').getDay()}
function routineDue(r,d=today()){return r.active!==false&&Array.isArray(r.days)&&r.days.map(Number).includes(weekday(d))}
function dueRoutines(d=today()){return S.routines.filter(r=>routineDue(r,d)).sort((a,b)=>(a.time||'23:59').localeCompare(b.time||'23:59'))}
function routineActivity(r,d=today()){return S.activities.find(a=>a.routineId===r.id&&a.date===d&&a.completed!==false)||null}
function routineSkip(r,d=today()){return S.routineSkips.find(x=>x.routineId===r.id&&x.date===d)||null}
function routineState(r,d=today()){if(routineActivity(r,d))return'completed';if(routineSkip(r,d))return'skipped';if(d<today())return'missed';if(d>today())return'upcoming';return (r.time&&localTime()>r.time)?'overdue':'pending'}
function completeRoutine(id,d=today()){const r=S.routines.find(x=>x.id===id);if(!r||routineActivity(r,d))return;S.routineSkips=S.routineSkips.filter(x=>!(x.routineId===id&&x.date===d));const a={id:uid('a'),date:d,startTime:d===today()?localTime():(r.time||'00:00'),plannedTime:r.time||null,title:r.title,category:r.category||'personal',duration:Math.max(1,+r.duration||30),goalId:r.goalId||null,source:'routine',completed:true,routineId:r.id,rhythm:'routine',obligation:r.obligation||'important',planned:true,notes:''};S.activities.push(a);save();toast(r.title+' selesai · +'+activityXP(a)+' XP');render()}
function skipRoutine(id,d=today()){const r=S.routines.find(x=>x.id===id);if(!r||routineActivity(r,d)||routineSkip(r,d))return;if(r.obligation==='mandatory'&&!confirm('Tandai kegiatan wajib ini sebagai dilewati?'))return;S.routineSkips.push({id:uid('skip'),routineId:id,date:d,time:d===today()?localTime():null,obligation:r.obligation||'important'});save();toast('Dicatat sebagai dilewati');render()}
function routineCompletion(d=today()){const due=dueRoutines(d);if(!due.length)return{due:0,done:0,mandatory:0,mandatoryDone:0,pct:0};const done=due.filter(r=>routineActivity(r,d)).length,mandatory=due.filter(r=>r.obligation==='mandatory').length,mandatoryDone=due.filter(r=>r.obligation==='mandatory'&&routineActivity(r,d)).length;return{due:due.length,done,mandatory,mandatoryDone,pct:Math.round(done/due.length*100)}}
function routineAdherence(days=30){let due=0,done=0,mandatoryDue=0,mandatoryDone=0;for(let i=0;i<days;i++){const d=add(today(),-i);for(const r of dueRoutines(d)){due++;if(routineActivity(r,d))done++;if(r.obligation==='mandatory'){mandatoryDue++;if(routineActivity(r,d))mandatoryDone++}}}return{due,done,pct:due?Math.round(done/due*100):0,mandatoryPct:mandatoryDue?Math.round(mandatoryDone/mandatoryDue*100):0}}
function spontaneousActivities(d=today()){return S.activities.filter(a=>a.date===d&&a.planned===false)}
function lifeTime(d=today()){return S.activities.filter(a=>a.date===d).reduce((n,a)=>n+(+a.duration||0),0)}
function routineRow(r,d=today()){const st=routineState(r,d),done=st==='completed',skipped=st==='skipped',late=st==='overdue'||st==='missed';return'<div class="routine-row '+st+'"><div class="routine-time">'+esc(r.time||'Fleksibel')+'</div><div class="routine-main"><div class="routine-title">'+esc(r.title)+'</div><div class="routine-meta"><span>'+cat(r.category)+'</span><span class="pill '+(r.obligation==='mandatory'?'red':r.obligation==='important'?'orange':'')+'">'+obligationLabel(r.obligation)+'</span><span>'+mins(r.duration)+'</span>'+(late?'<span class="routine-alert">Terlambat</span>':'')+'</div></div><div class="routine-actions">'+(done?'<span class="routine-done">✓ Selesai</span>':skipped?'<span class="routine-skipped">Dilewati</span>':'<button class="mini-btn routine-complete" data-act="completeRoutine" data-id="'+r.id+'">✓ Done</button><button class="mini-btn" data-act="skipRoutine" data-id="'+r.id+'">Skip</button>')+'</div></div>'}
function todayLifeCard(){const due=dueRoutines(),rc=routineCompletion();return'<article class="card life-today-card" data-widget="life"><div class="card-head"><div><h2>Life Plan Hari Ini</h2><p>'+rc.done+'/'+rc.due+' kegiatan rutin selesai.</p></div><button class="btn btn-ghost" data-route="life">Buka Life Log →</button></div><div class="routine-list">'+(due.length?due.slice(0,6).map(r=>routineRow(r)).join(''):'<div class="empty empty-compact">Belum ada rutinitas untuk hari ini.</div>')+'</div>'+(due.length>6?'<div class="item-meta" style="margin-top:9px">+'+(due.length-6)+' kegiatan lainnya</div>':'')+'</article>'}
let undoStack=[],lastSavedJSON=JSON.stringify(S),autoCloudTimer=null,historyTimer=null,suppressAutoCloud=false;
function recoveryDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('desca-os-recovery-v1',1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('versions')){const s=db.createObjectStore('versions',{keyPath:'id'});s.createIndex('createdAt','createdAt')}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function recoverySnapshotState(raw=S){const x=JSON.parse(JSON.stringify(raw));if(x.settings){delete x.settings.supabaseAnonKey;delete x.settings.googleClientId}return x}
async function addVersionSnapshot(snapshot,label='Checkpoint'){try{const db=await recoveryDB(),tx=db.transaction('versions','readwrite'),store=tx.objectStore('versions');store.put({id:uid('ver'),createdAt:new Date().toISOString(),label,revision:snapshot?.meta?.revision||0,state:recoverySnapshotState(snapshot)});await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});const db2=await recoveryDB(),tx2=db2.transaction('versions','readwrite'),all=await new Promise((res,rej)=>{const q=tx2.objectStore('versions').getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)});all.sort((a,b)=>a.createdAt.localeCompare(b.createdAt));for(const v of all.slice(0,Math.max(0,all.length-20)))tx2.objectStore('versions').delete(v.id)}catch{}}
function queueVersionSnapshot(prev,label='Auto checkpoint'){clearTimeout(historyTimer);historyTimer=setTimeout(()=>addVersionSnapshot(prev,label),1200)}
async function listVersionSnapshots(){try{const db=await recoveryDB(),tx=db.transaction('versions','readonly'),rows=await new Promise((res,rej)=>{const q=tx.objectStore('versions').getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)});return rows.sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}catch{return[]}}
async function restoreVersion(id){const db=await recoveryDB(),tx=db.transaction('versions','readonly'),v=await new Promise((res,rej)=>{const q=tx.objectStore('versions').get(id);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});if(!v?.state)return;if(!confirm('Pulihkan state dari checkpoint ini? State saat ini akan masuk Version History terlebih dahulu.'))return;await addVersionSnapshot(S,'Sebelum restore');const keep={supabaseUrl:S.settings.supabaseUrl,supabaseAnonKey:S.settings.supabaseAnonKey,googleClientId:S.settings.googleClientId};S=v.state;S.settings={...seed().settings,...S.settings,...keep};S.meta={...seed().meta,...S.meta};lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);syncPomodoro();toast('Version dipulihkan');render()}
function scheduleAutoCloudSync(){if(suppressAutoCloud||!S.settings.autoCloudSync||!cloudSession?.user?.id||!cloudConfigured())return;clearTimeout(autoCloudTimer);autoCloudTimer=setTimeout(()=>cloudSave(true),2500)}
function save(reason='Update'){const nowJSON=JSON.stringify(S);if(nowJSON===lastSavedJSON){side();return}let prev=null;try{prev=JSON.parse(lastSavedJSON)}catch{}if(prev){undoStack.push({label:reason,state:prev});if(undoStack.length>8)undoStack.shift();queueVersionSnapshot(prev,reason)}S.meta.revision=(+S.meta.revision||0)+1;S.meta.modifiedAt=new Date().toISOString();lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);side();scheduleAutoCloudSync();syncBackgroundReminders()}
function undoLast(){const u=undoStack.pop();if(!u){toast('Tidak ada perubahan yang bisa di-undo');return}const current=S;S=u.state;S.settings={...seed().settings,...S.settings};S.meta={...seed().meta,...S.meta};queueVersionSnapshot(current,'Sebelum undo');lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);syncPomodoro();toast('Undo: '+u.label);render()}
const goal=id=>S.goals.find(g=>g.id===id)?.title||'',cat=c=>C[c]?.[0]||c||'General';
const xp=()=>S.activities.reduce((a,x)=>a+activityXP(x),0)+S.tasks.filter(x=>x.status==='done').reduce((a,x)=>a+taskXP(x),0),level=()=>({level:Math.floor(xp()/1200)+1,cur:xp()%1200,pct:Math.round((xp()%1200)/12)});

