function moveTrash(type,id,label='Item'){const map={task:S.tasks,routine:S.routines,goal:S.goals,finance:S.finance,budget:S.budgets,investment:S.investments,financeGoal:S.financeGoals,recurringFinance:S.recurringFinance,debt:S.debts,dmathContent:S.dmath.content,quranEntry:S.quran.entries,run:S.runs,project:S.projects,studyTopic:S.studyTopics,studyTest:S.studyTests,researchPaper:S.researchPapers,researchNote:S.researchNotes};const arr=map[type];if(!arr)return;const i=arr.findIndex(x=>x.id===id);if(i<0)return;const item=arr[i],linkedActivity=type==='run'?S.activities.find(a=>a.runId===id)||null:null;S.trash.push({id:uid('trash'),entityType:type,entityId:id,label:label||item.title||item.name||type,data:JSON.parse(JSON.stringify(item)),relatedActivity:linkedActivity?JSON.parse(JSON.stringify(linkedActivity)):null,deletedAt:new Date().toISOString()});arr.splice(i,1);if(linkedActivity)S.activities=S.activities.filter(a=>a.id!==linkedActivity.id);S.trash=S.trash.filter(x=>Date.now()-Date.parse(x.deletedAt)<30*86400000).slice(-200);save('Delete '+type);toast('Dipindah ke Trash');close();render()}
function restoreTrash(id){const t=S.trash.find(x=>x.id===id);if(!t)return;const map={task:S.tasks,routine:S.routines,goal:S.goals,finance:S.finance,budget:S.budgets,investment:S.investments,financeGoal:S.financeGoals,recurringFinance:S.recurringFinance,debt:S.debts,dmathContent:S.dmath.content,quranEntry:S.quran.entries,run:S.runs,project:S.projects,studyTopic:S.studyTopics,studyTest:S.studyTests,researchPaper:S.researchPapers,researchNote:S.researchNotes},arr=map[t.entityType];if(!arr)return;if(!arr.some(x=>x.id===t.entityId))arr.push(t.data);if(t.relatedActivity&&!S.activities.some(a=>a.id===t.relatedActivity.id))S.activities.push(t.relatedActivity);S.trash=S.trash.filter(x=>x.id!==id);save('Restore '+t.entityType);toast('Item dipulihkan');render()}
function emptyTrash(){if(!S.trash.length)return;if(confirm('Hapus semua isi Trash secara permanen?')){S.trash=[];save('Empty trash');render()}}
async function recoveryPage(){const conflict=S.meta.cloudConflict;$('#page').innerHTML=head('Recovery','Undo, Trash, Version History, dan penyelesaian konflik cloud.','<button class="btn btn-secondary" data-act="undo">↶ Undo</button>')+(conflict?'<article class="card recovery-conflict"><div class="card-head"><div><h2>Cloud Conflict</h2><p>Local revision '+conflict.localRevision+' dan cloud revision '+conflict.remoteRevision+' sama-sama berubah.</p></div><span class="pill red">ACTION REQUIRED</span></div><div class="button-row"><button class="btn btn-primary" data-act="resolveCloud" data-choice="local">Gunakan Local</button><button class="btn btn-secondary" data-act="resolveCloud" data-choice="cloud">Gunakan Cloud</button></div></article>':'')+'<div class="grid two-col"><article class="card"><div class="card-head"><div><h2>Trash</h2><p>Item dihapus disimpan hingga 30 hari.</p></div><button class="mini-btn" data-act="emptyTrash">Empty</button></div><div class="simple-list">'+(S.trash.length?S.trash.slice().reverse().map(t=>'<div class="list-row"><div class="item-main"><div class="item-title">'+esc(t.label)+'</div><div class="item-meta">'+esc(t.entityType)+' • '+new Date(t.deletedAt).toLocaleString('id-ID')+'</div></div><button class="mini-btn" data-act="restoreTrash" data-id="'+t.id+'">Restore</button></div>').join(''):'<div class="empty">Trash kosong.</div>')+'</div></article><article class="card"><div class="card-head"><div><h2>Version History</h2><p>20 checkpoint terakhir disimpan di perangkat.</p></div></div><div id="versionHistoryList"><div class="empty">Memuat checkpoint...</div></div></article></div>';const rows=await listVersionSnapshots();if(route!=='recovery')return;const box=$('#versionHistoryList');if(box)box.innerHTML=rows.length?'<div class="simple-list">'+rows.map(v=>'<div class="list-row"><div class="item-main"><div class="item-title">'+esc(v.label||'Checkpoint')+'</div><div class="item-meta">Revision '+v.revision+' • '+new Date(v.createdAt).toLocaleString('id-ID')+'</div></div><button class="mini-btn" data-act="restoreVersion" data-id="'+v.id+'">Restore</button></div>').join('')+'</div>':'<div class="empty">Belum ada checkpoint.</div>'}
function reminderTimestamp(date,time){if(!date||!time)return 0;const suffix=S.profile.timezone==='Asia/Jakarta'?'+07:00':'';return Date.parse(date+'T'+time+':00'+suffix)}
function backgroundReminderPayload(){const lead=clamp(+S.settings.reminderLead||30,0,180),out=[],seen=new Set(),push=(id,title,body,at)=>{if(!at||at<Date.now()-60000||seen.has(id))return;seen.add(id);out.push({id,title,body,at})};for(const t of S.tasks.filter(x=>x.status!=='done'&&x.date&&x.startTime&&x.date>=today()&&x.date<=add(today(),7))){const at=reminderTimestamp(t.date,t.startTime)-lead*60000;push('task-'+t.id+'-'+t.date,'Task segera dimulai',t.startTime+' • '+t.title,at)}for(let i=0;i<7;i++){const d=add(today(),i);for(const r of dueRoutines(d).filter(x=>x.time)){push('routine-'+r.id+'-'+d,'Routine segera dimulai',r.time+' • '+r.title,reminderTimestamp(d,r.time)-lead*60000)}}for(const q of S.quran.entries.filter(x=>x.nextReview&&x.nextReview>=today()&&x.nextReview<=add(today(),7))){push('quran-'+q.id+'-'+q.nextReview,'Murajaah '+q.surah,'Ayat '+q.fromAyah+(+q.toAyah!==+q.fromAyah?'–'+q.toAyah:''),reminderTimestamp(q.nextReview,'08:00'))}return out.slice(0,150)}
async function syncBackgroundReminders(){if(!('serviceWorker'in navigator)||!S.settings.notifications)return;try{const reg=await navigator.serviceWorker.ready,reminders=backgroundReminderPayload();(reg.active||navigator.serviceWorker.controller)?.postMessage({type:'SYNC_REMINDERS',reminders});if('periodicSync'in reg){try{await reg.periodicSync.register('desca-reminders',{minInterval:15*60*1000})}catch{}}if('sync'in reg){try{await reg.sync.register('desca-reminders')}catch{}}}catch{}}
function backgroundNotificationStatus(){if(!('serviceWorker'in navigator))return'Unsupported';if('PeriodicSyncManager'in window)return'Background capable';if('SyncManager'in window)return'Background sync limited';return'Foreground fallback'}
function notificationSupported(){return 'Notification' in window}
async function requestNotifications(){if(!notificationSupported()){toast('Browser ini tidak mendukung notification');return}const p=await Notification.requestPermission();S.settings.notifications=p==='granted';save('Notification permission');if(p==='granted')await syncBackgroundReminders();toast(p==='granted'?'Notification aktif':'Izin notification belum diberikan');render()}
function notifyOnce(key,title,body){if(!S.settings.notifications||!notificationSupported()||Notification.permission!=='granted'||S.reminderLog.includes(key))return;S.reminderLog.push(key);S.reminderLog=S.reminderLog.slice(-300);save('Reminder sent');if('serviceWorker'in navigator)navigator.serviceWorker.ready.then(reg=>reg.showNotification(title,{body,icon:'./assets/icon-192.png',tag:key,data:{url:'./'}})).catch(()=>{});else try{new Notification(title,{body,icon:'./assets/icon-192.png',tag:key})}catch{}}
function checkReminders(){if(!S.settings.notifications)return;const now=minutesFromHHMM(localTime()),lead=clamp(+S.settings.reminderLead||30,0,180),d=today(),tom=add(d,1);for(const t of S.tasks.filter(x=>x.status!=='done')){if(t.date===d&&t.startTime){const tm=minutesFromHHMM(t.startTime),delta=tm-now;if(delta>=0&&delta<=lead)notifyOnce('task-'+t.id+'-'+d,'Task segera dimulai',t.startTime+' • '+t.title);if(delta<0&&delta>=-60)notifyOnce('late-'+t.id+'-'+d,'Task belum selesai',t.title+' sudah melewati jam '+t.startTime)}if(t.deadline===tom)notifyOnce('deadline-'+t.id+'-'+tom,'Deadline besok',t.title)}for(const r of dueRoutines(d).filter(x=>!routineActivity(x,d)&&!routineSkip(x,d)&&x.time)){const tm=minutesFromHHMM(r.time),delta=tm-now;if(delta>=0&&delta<=lead)notifyOnce('routine-'+r.id+'-'+d,'Routine segera dimulai',r.time+' • '+r.title);if(delta<0&&delta>=-60)notifyOnce('routine-late-'+r.id+'-'+d,'Routine belum selesai',r.title+' melewati jam '+r.time)}const month=d.slice(0,7);for(const b of S.budgets.filter(x=>x.month===month)){const spent=S.finance.filter(x=>x.type==='expense'&&x.date?.startsWith(month)&&(x.category||'').toLowerCase()===(b.category||'').toLowerCase()).reduce((n,x)=>n+(+x.amount||0),0);if(b.limit&&spent/b.limit>=.8)notifyOnce('budget-'+b.id+'-'+month,'Budget '+b.category+' hampir habis',Math.round(spent/b.limit*100)+'% terpakai')}const lastStudy=S.activities.filter(x=>['study','research','english'].includes(x.category)).slice().sort((a,b)=>b.date.localeCompare(a.date))[0];if(!lastStudy||lastStudy.date<add(d,-2))notifyOnce('study-gap-'+d,'Belum ada sesi belajar beberapa hari','Cek kembali target belajarmu jika memang masih relevan.');for(const q of quranDueEntries(d)){notifyOnce('quran-'+q.id+'-'+d,'Murajaah hari ini',q.surah+' ayat '+q.fromAyah+(+q.toAyah!==+q.fromAyah?'–'+q.toAyah:''))}
const lastHealth=S.healthLogs.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];if(!lastHealth||lastHealth.date<add(d,-2))notifyOnce('health-gap-'+d,'Health log belum diperbarui','Catat tidur, energi, atau aktivitas fisik bila ingin menjaga histori tetap lengkap.')}
function commandParse(raw){const q=raw.trim();let m;if((m=q.match(/^spent\s+(\d+)\s+(.+)/i)))return{type:'expense',amount:+m[1],title:m[2]};if((m=q.match(/^income\s+(\d+)\s+(.+)/i)))return{type:'income',amount:+m[1],title:m[2]};if((m=q.match(/^(studied|study)\s+(\d+)m\s+(.+)/i)))return{type:'activity',duration:+m[2],title:m[3],category:'study'};if((m=q.match(/^timer\s+(study|research|project|dmath|quran|health|english|personal|finance)?\s*(.+)/i)))return{type:'timer',category:(m[1]||'personal').toLowerCase(),title:m[2]||'Activity'};if((m=q.match(/^task\s+(.+)/i))){let title=m[1],date=today(),time='',estimate=60,category='personal',priority='medium';if(/\btomorrow\b/i.test(title)){date=add(today(),1);title=title.replace(/\btomorrow\b/i,'').trim()}const tm=title.match(/\b([01]\d|2[0-3]):[0-5]\d\b/);if(tm){time=tm[0];title=title.replace(tm[0],'').trim()}const dm=title.match(/\b(\d+)m\b/i);if(dm){estimate=+dm[1];title=title.replace(dm[0],'').trim()}for(const k of Object.keys(C))if(new RegExp('\\b'+k+'\\b','i').test(title)){category=k;title=title.replace(new RegExp('\\b'+k+'\\b','i'),'').trim()}for(const p of ['high','medium','low'])if(new RegExp('\\b'+p+'\\b','i').test(title)){priority=p;title=title.replace(new RegExp('\\b'+p+'\\b','i'),'').trim()}return{type:'task',title,date,time,estimate,category,priority}}return null}
function executeCommand(raw){const x=commandParse(raw);if(!x)return false;if(x.type==='expense'||x.type==='income'){S.finance.push({id:uid('f'),title:x.title,type:x.type,amount:x.amount,category:'General',date:today(),notes:'Quick command'});save();toast('Finance tercatat');render();return true}if(x.type==='activity'){const a={id:uid('a'),date:today(),title:x.title,category:x.category,duration:x.duration,startTime:localTime(),source:'command',completed:true,rhythm:'nonroutine',obligation:'important',planned:false,notes:''};S.activities.push(a);save();toast('Study tercatat · +'+activityXP(a)+' XP');render();return true}if(x.type==='timer'){startUniversalTimer(x);return true}if(x.type==='task'){S.tasks.push({id:uid('t'),title:x.title,date:x.date,startTime:x.time,status:'planned',priority:x.priority,category:x.category,goalId:null,estimate:x.estimate,inbox:false,notes:'',subtasks:[],tags:[],recurrence:'none'});save();toast('Task dibuat dari command');render();return true}return false}

function healthLog(d=today()){return S.healthLogs.find(x=>x.date===d)||null}
