function runCard(r){const pace=runPaceSec(r),z=runHRZone(r.avgHR);return'<article class="run-card"><div class="run-card-top"><div><span class="run-type">'+esc(runTypeLabel(r.type))+'</span><h3>'+esc(r.title||runTypeLabel(r.type))+'</h3><p>'+fmt(r.date,{weekday:'short',day:'numeric',month:'short',year:'numeric'})+(r.startTime?' • '+r.startTime:'')+'</p></div><div class="button-row compact"><button class="mini-btn" data-act="viewRun" data-id="'+r.id+'">Details</button><button class="mini-btn" data-act="editRun" data-id="'+r.id+'">Edit</button></div></div><div class="run-core-metrics"><div><span>Distance</span><b>'+r.distanceKm.toFixed(2)+' km</b></div><div><span>Time</span><b>'+runDurationText(r.durationSec)+'</b></div><div><span>Pace</span><b>'+runPaceText(pace)+'</b></div><div><span>Speed</span><b>'+runSpeedKmh(r).toFixed(1)+' km/h</b></div></div><div class="run-detail-grid">'+(r.avgHR?'<span>♥ Avg HR <b>'+r.avgHR+' bpm</b></span>':'')+(r.maxHR?'<span>Max HR <b>'+r.maxHR+' bpm</b></span>':'')+(z?'<span>HR Zone <b>Z'+z+'</b></span>':'')+(r.cadence?'<span>Cadence <b>'+r.cadence+' spm</b></span>':'')+(r.strideCm?'<span>Stride <b>'+r.strideCm+' cm</b></span>':'')+(r.elevationGain?'<span>Elevation <b>+'+r.elevationGain+' m</b></span>':'')+(r.powerW?'<span>Power <b>'+r.powerW+' W</b></span>':'')+(r.rpe?'<span>RPE <b>'+r.rpe+'/10</b></span>':'')+'</div>'+(r.splits?.length?'<div class="run-split-preview">'+r.splits.slice(0,5).map(s=>'<span><b>'+esc(s.lap)+'</b> '+runPaceText(s.paceSec)+(s.hr?' • '+s.hr+' bpm':'')+'</span>').join('')+(r.splits.length>5?'<small>+'+(r.splits.length-5)+' split lainnya</small>':'')+'</div>':'')+(r.notes?'<div class="run-note">'+esc(r.notes)+'</div>':'')+'</article>'}
function runningPage(){const runs=S.runs.slice().sort((a,b)=>(b.date+(b.startTime||'')).localeCompare(a.date+(a.startTime||''))),weekKm=runWeekDistance(),goalKm=Math.max(1,+S.settings.runningWeeklyGoalKm||20),weekRuns=runs.filter(x=>x.date>=runWeekStart()),weekTime=weekRuns.reduce((n,x)=>n+(+x.durationSec||0),0),weekLoad=runningLoad(7),load28=runningLoad(28),recent=runs.slice(0,12),weekly=runWeeklySeries(8),avgPace=weekRuns.length?Math.round(weekRuns.reduce((n,x)=>n+runPaceSec(x),0)/weekRuns.length):0,avgHR=weekRuns.filter(x=>x.avgHR).length?Math.round(weekRuns.filter(x=>x.avgHR).reduce((n,x)=>n+(+x.avgHR||0),0)/weekRuns.filter(x=>x.avgHR).length):0,totalKm=runs.reduce((n,x)=>n+(+x.distanceKm||0),0),r28=runs.filter(x=>x.date>=add(today(),-27)),cad28=r28.filter(x=>x.cadence).length?Math.round(r28.filter(x=>x.cadence).reduce((n,x)=>n+(+x.cadence||0),0)/r28.filter(x=>x.cadence).length):0,elev28=Math.round(r28.reduce((n,x)=>n+(+x.elevationGain||0),0));$('#page').innerHTML=head('Running','Track pace, heart rate, cadence, elevation, splits, training load, dan mileage secara lengkap.','<button class="btn btn-secondary" data-act="runningSettings">⚙ Settings</button><button class="btn btn-primary" data-act="newRun">+ Log Run</button>')+'<section class="running-hero"><div><div class="eyebrow">RUNNING DASHBOARD</div><h1>'+weekKm.toFixed(1)+' / '+goalKm.toFixed(1)+' km minggu ini</h1><p>'+weekRuns.length+' sesi • '+runDurationText(weekTime)+' waktu lari • '+runningActiveWeekStreak()+' active-week streak</p>'+prog(weekKm/goalKm*100)+'</div><div class="running-hero-pace"><span>Avg Pace Minggu Ini</span><b>'+runPaceText(avgPace)+'</b><small>'+(avgHR?avgHR+' bpm avg HR':'Belum ada HR')+'</small></div></section><section class="grid metric-grid compact-metrics">'+metric('Weekly Distance',weekKm.toFixed(1)+' km',Math.round(weekKm/goalKm*100)+'% target','↗')+metric('Run Time',runDurationText(weekTime),weekRuns.length+' sesi','◷')+metric('sRPE Load',num(weekLoad),'7 hari • 28D '+num(load28),'▤')+metric('Total Distance',totalKm.toFixed(1)+' km',runs.length+' sesi tercatat','◎')+metric('Active Weeks',runningActiveWeekStreak(),'Streak minggu dengan lari','🔥')+metric('Avg Cadence',cad28?cad28+' spm':'—','28 hari','⌁')+metric('Elevation',elev28?num(elev28)+' m':'—','Gain 28 hari','△')+'</section><div class="grid two-col"><article class="card chart-card"><div class="card-head"><div><h2>Weekly Mileage</h2><p>Volume jarak 8 minggu terakhir.</p></div></div>'+lineChart(weekly.map(x=>x.km),weekly.map(x=>x.label),{suffix:'km'})+'</article><article class="card"><div class="card-head"><div><h2>Heart Rate Zones</h2><p>Distribusi durasi berdasarkan average HR sesi.</p></div><span class="pill blue">Max '+S.settings.runningMaxHR+' bpm</span></div>'+runZoneDistribution(28)+'</article></div><div class="grid two-col section-gap"><article class="card"><div class="card-head"><div><h2>Recent Pace Trend</h2><p>Semakin pendek pace, semakin cepat.</p></div></div>'+runningRecentTrend()+'</article><article class="card"><div class="card-head"><div><h2>Best Recorded Sessions</h2><p>Ringkasan terbaik dari sesi yang benar-benar dicatat.</p></div></div>'+runningBestCards()+'</article></div><article class="card section-gap"><div class="card-head"><div><h2>Run History</h2><p>Semua metrik per sesi, termasuk HR, cadence, elevation, dan splits.</p></div><button class="mini-btn" data-act="newRun">+ Run</button></div><div class="run-history">'+(recent.length?recent.map(runCard).join(''):'<div class="empty empty-state-large"><span class="empty-icon">↗</span><b>Belum ada sesi lari.</b><small>Log lari pertama untuk mulai melihat pace, heart rate, mileage, dan trend latihan.</small><button class="btn btn-primary" data-act="newRun">Log Run Pertama</button></div>')+'</div>'+(runs.length>recent.length?'<div class="item-meta" style="margin-top:12px">Menampilkan 12 sesi terbaru dari '+runs.length+' total.</div>':'')+'</article>'}
function runDistanceOn(d=today()){const km=S.runs.filter(x=>x.date===d).reduce((n,x)=>n+(+x.distanceKm||0),0);return km||(+healthLog(d)?.runKm||0)}
function healthPage(){const a=S.activities.filter(x=>x.category==='health'&&x.source!=='running').slice().reverse(),h=healthLog(),assoc=healthAssociation(),logs=S.healthLogs.slice().sort((a,b)=>b.date.localeCompare(a.date)),sleep=logs.slice(0,14).reverse();$('#page').innerHTML=head('Health','Tidur, langkah, berat, air, energi, mood, dan workout umum. Detail lari ada di Running.','<button class="btn btn-secondary" data-route="running">Running →</button><button class="btn btn-primary" data-act="logHealth">+ Health Log</button>')+'<section class="grid metric-grid">'+metric('Sleep',h?.sleep?h.sleep+'j':'—','Hari ini','☾')+metric('Steps',h?.steps?num(h.steps):'—','Hari ini','⌁')+metric('Run',runDistanceOn()?runDistanceOn().toFixed(2)+' km':'—','Ringkasan dari Running','↗')+metric('Energy',h?.energy?h.energy+'/5':'—','Self-report','⚡')+metric('Health Time',mins(catMin('health',7)),'7 hari','♥')+'</section><div class="grid two-col"><article class="card chart-card"><div class="card-head"><div><h2>Sleep 14 Days</h2><p>Jam tidur yang kamu catat.</p></div></div>'+lineChart(sleep.map(x=>+x.sleep||0),sleep.map(x=>fmt(x.date,{day:'numeric',month:'short'})),{suffix:'jam'})+'</article><article class="card"><div class="card-head"><div><h2>Historical Association</h2><p>Perbandingan deskriptif, bukan sebab-akibat.</p></div></div><div class="simple-list"><div class="list-row"><div class="item-main"><div class="item-title">Tidur ≥7 jam</div><div class="item-meta">Rata-rata productive time '+mins(assoc.good)+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Tidur <7 jam</div><div class="item-meta">Rata-rata productive time '+mins(assoc.low)+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Hari olahraga</div><div class="item-meta">Rata-rata productive time '+mins(assoc.work)+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Hari tanpa olahraga</div><div class="item-meta">Rata-rata productive time '+mins(assoc.rest)+'</div></div></div></div><div class="callout" style="margin-top:12px">Berdasarkan '+assoc.n+' health log dalam 60 hari. Angka ini hanya menunjukkan asosiasi pada histori pribadi.</div></article></div><div class="grid two-col section-gap"><article class="card"><div class="card-head"><h2>Recent Health Logs</h2></div><div class="simple-list">'+(logs.length?logs.slice(0,14).map(x=>'<div class="list-row"><div class="item-main"><div class="item-title">'+fmt(x.date,{weekday:'short',day:'numeric',month:'short'})+'</div><div class="item-meta">'+(x.sleep?x.sleep+'j tidur • ':'')+(x.steps?num(x.steps)+' steps • ':'')+(x.energy?'energi '+x.energy+'/5 • ':'')+(x.mood?'mood '+x.mood+'/5':'')+'</div></div><button class="mini-btn" data-act="editHealth" data-date="'+x.date+'">Edit</button></div>').join(''):'<div class="empty">Belum ada health log.</div>')+'</div></article><article class="card"><div class="card-head"><h2>Other Health Activities</h2></div><div class="timeline">'+(a.length?a.slice(0,12).map(x=>'<div class="timeline-item"><div class="item-main"><div class="item-title">'+esc(x.title)+'</div><div class="item-meta">'+fmt(x.date,{day:'numeric',month:'short'})+' • '+mins(x.duration)+'</div></div></div>').join(''):'<div class="empty">Belum ada aktivitas health selain running.</div>')+'</div></article></div>'}
function recurringFinanceForm(x={}){return'<form id="recurringFinanceForm"><div class="form-grid"><div class="field full"><label>Nama</label><input name="title" required value="'+esc(x.title||'')+'" placeholder="Kos / Langganan / Gaji"></div><div class="field"><label>Tipe</label><select name="type"><option value="expense" '+(x.type!=='income'?'selected':'')+'>Pengeluaran</option><option value="income" '+(x.type==='income'?'selected':'')+'>Pemasukan</option></select></div><div class="field"><label>Nominal</label><input name="amount" type="number" min="0" required value="'+(+x.amount||'')+'"></div><div class="field"><label>Kategori</label><input name="category" value="'+esc(x.category||'General')+'"></div><div class="field"><label>Tanggal setiap bulan</label><input name="day" type="number" min="1" max="28" value="'+(+x.day||1)+'"></div><div class="field"><label>Klasifikasi</label><select name="bucket">'+['needs','wants','savings','investment'].map(v=>'<option value="'+v+'" '+(x.bucket===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Recurring</button></form>'}
