function queueGoogleCalendarRefresh(){if(!googleReady()||G.busy)return;const last=S.settings.googleLastSync?Date.parse(S.settings.googleLastSync):0;if(Date.now()-last<5*60*1000)return;setTimeout(()=>{if(route==='calendar'&&googleReady()&&!G.busy)googleSyncAll()},0)}
