async function cloudLogin(email,password,signup=false){if(!cloudConfigured()){toast('Isi Supabase URL dan anon key dulu');return}try{const path=signup?'/auth/v1/signup':'/auth/v1/token?grant_type=password',body=await cloudRequest(path,{method:'POST',body:JSON.stringify({email,password})});if(body.access_token){cloudSession=body;sessionStorage.setItem(CLOUD_SESSION_KEY,JSON.stringify(body));toast('Cloud login berhasil');await cloudAutoReconcile();render()}else toast(signup?'Akun dibuat. Cek email jika konfirmasi diaktifkan.':'Login belum berhasil')}catch(e){toast(e.message)}}
function cloudLogout(){cloudSession=null;sessionStorage.removeItem(CLOUD_SESSION_KEY);clearTimeout(autoCloudTimer);toast('Cloud session ditutup');render()}
async function cloudSave(quiet=false,force=false){if(!cloudSession?.user?.id){if(!quiet)toast('Login cloud terlebih dahulu');return false}try{const rows=await cloudRequest('/rest/v1/desca_state?user_id=eq.'+encodeURIComponent(cloudSession.user.id)+'&select=payload,updated_at&limit=1'),remote=rows?.[0]||null,remoteRev=+remote?.payload?.meta?.revision||0,last=+S.meta.lastCloudRevision||0,localRev=+S.meta.revision||0,remoteChanged=remoteRev>last,localChanged=localRev>last;if(remote&&remoteChanged&&localChanged&&!force){S.meta.cloudConflict={remoteRevision:remoteRev,localRevision:localRev,remoteUpdatedAt:remote.updated_at||'',detectedAt:new Date().toISOString()};lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);if(!quiet)toast('Cloud conflict terdeteksi. Buka Recovery.');render();return false}const payload=recoverySnapshotState(S),now=new Date().toISOString();delete payload.settings.supabaseAnonKey;payload.meta={...payload.meta,lastCloudSync:now,lastCloudRevision:localRev,cloudConflict:null};await cloudRequest('/rest/v1/desca_state?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({user_id:cloudSession.user.id,payload,updated_at:now})});S.meta.lastCloudSync=now;S.meta.lastCloudRevision=localRev;S.meta.cloudConflict=null;lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);if(!quiet)toast('Cloud sync selesai');return true}catch(e){if(!quiet)toast('Cloud save gagal: '+e.message);return false}}
async function cloudLoad(force=false){if(!cloudSession?.user?.id){toast('Login cloud terlebih dahulu');return false}try{const rows=await cloudRequest('/rest/v1/desca_state?user_id=eq.'+encodeURIComponent(cloudSession.user.id)+'&select=payload,updated_at&limit=1'),remote=rows?.[0];if(!remote?.payload){toast('Belum ada backup cloud');return false}if(!force&&S.meta.modifiedAt&&S.meta.lastCloudSync&&S.meta.modifiedAt>S.meta.lastCloudSync&&(+remote.payload?.meta?.revision||0)>(+S.meta.lastCloudRevision||0)){S.meta.cloudConflict={remoteRevision:+remote.payload.meta.revision||0,localRevision:+S.meta.revision||0,remoteUpdatedAt:remote.updated_at||'',detectedAt:new Date().toISOString()};lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);toast('Cloud conflict terdeteksi');render();return false}await addVersionSnapshot(S,'Sebelum cloud restore');const cfg={supabaseUrl:S.settings.supabaseUrl,supabaseAnonKey:S.settings.supabaseAnonKey,googleClientId:S.settings.googleClientId};suppressAutoCloud=true;S=remote.payload;S.settings={...seed().settings,...S.settings,...cfg};S.meta={...seed().meta,...S.meta,lastCloudSync:new Date().toISOString(),lastCloudRevision:+S.meta?.revision||0,cloudConflict:null};lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);suppressAutoCloud=false;syncPomodoro();toast('Data cloud dimuat');render();return true}catch(e){suppressAutoCloud=false;toast('Cloud load gagal: '+e.message);return false}}
async function cloudAutoReconcile(){if(!cloudSession?.user?.id||!cloudConfigured())return;try{const rows=await cloudRequest('/rest/v1/desca_state?user_id=eq.'+encodeURIComponent(cloudSession.user.id)+'&select=payload,updated_at&limit=1'),remote=rows?.[0];if(!remote){await cloudSave(true,true);return}const remoteRev=+remote.payload?.meta?.revision||0,last=+S.meta.lastCloudRevision||0,localRev=+S.meta.revision||0;if(remoteRev>last&&localRev<=last){await cloudLoad(true);return}if(remoteRev>last&&localRev>last){S.meta.cloudConflict={remoteRevision:remoteRev,localRevision:localRev,remoteUpdatedAt:remote.updated_at||'',detectedAt:new Date().toISOString()};lastSavedJSON=JSON.stringify(S);localStorage.setItem(K,lastSavedJSON);toast('Cloud conflict perlu diselesaikan');return}if(localRev>last)await cloudSave(true,true)}catch{}}
async function resolveCloudConflict(choice){if(choice==='local')await cloudSave(false,true);else if(choice==='cloud')await cloudLoad(true)}
let focus={phase:'focus',cycle:1,running:false,timer:null,startedAt:null,endsAt:null,work:S.settings.pomodoroFocus,short:S.settings.pomodoroShortBreak,long:S.settings.pomodoroLongBreak,total:S.settings.pomodoroFocus*60,left:S.settings.pomodoroFocus*60,category:'study',label:'Belajar Fokus',zen:false};
function focusPhaseLabel(){return focus.phase==='focus'?'FOKUS':focus.phase==='longBreak'?'ISTIRAHAT PANJANG':'ISTIRAHAT'}
function focusTimeText(){return String(Math.floor(focus.left/60)).padStart(2,'0')+':'+String(focus.left%60).padStart(2,'0')}
function ensureFocusOverlay(){let z=$('#focusZen');if(z)return z;z=document.createElement('section');z.id='focusZen';z.className='focus-zen';z.hidden=true;z.setAttribute('aria-live','polite');z.innerHTML='<div class="zen-top"><div class="zen-brand"><span class="brand-mark">D</span><div><b>Desca OS</b><small>Focus Mode</small></div></div><button class="zen-minimize" data-act="minimizeFocus" type="button">Minimize</button></div><div class="zen-center"><div class="zen-phase" id="zenPhase">FOKUS</div><div class="zen-session" id="zenSession">Belajar Fokus</div><div class="zen-clock-wrap"><div class="zen-ring" id="zenRing"><div class="zen-clock" id="zenClock">25:00</div></div></div><div class="zen-meta"><span id="zenCategory">Study</span><span>•</span><span id="zenCycle">Sesi 1 / 4</span></div><div class="zen-actions"><button class="zen-main" data-act="focus" type="button" id="zenPlay">Pause</button><button class="zen-secondary" data-act="resetFocus" type="button">Akhiri sesi</button><button class="zen-secondary" data-act="skipBreak" type="button" id="zenSkip">Lewati istirahat</button></div><div class="zen-tip">Space untuk pause/resume • Esc untuk minimize</div></div>';document.body.append(z);let d=document.createElement('button');d.id='focusDock';d.className='focus-dock';d.hidden=true;d.type='button';d.dataset.act='restoreFocus';d.innerHTML='<span class="focus-dock-dot"></span><span><b id="dockClock">25:00</b><small id="dockLabel">Focus Mode</small></span><span>↗</span>';document.body.append(d);return z}
function tryNativeFullscreen(){const el=document.documentElement;if(!document.fullscreenElement&&el.requestFullscreen)el.requestFullscreen().catch(()=>{})}
function exitNativeFullscreen(){if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}
function updateFocusOverlay(){const z=ensureFocusOverlay(),dock=$('#focusDock'),cycles=clamp(+S.settings.pomodoroCycles||4,1,12),pct=clamp((1-focus.left/Math.max(1,focus.total))*100,0,100),active=!!(focus.startedAt||focus.running||focus.phase!=='focus');z.hidden=!focus.zen;dock.hidden=focus.zen||!active;document.body.classList.toggle('focus-zen-active',focus.zen);$('#zenPhase').textContent=focusPhaseLabel();$('#zenSession').textContent=focus.phase==='focus'?(focus.label||'Belajar Fokus'):'Pulihkan energi';$('#zenClock').textContent=focusTimeText();$('#zenCategory').textContent=cat(focus.category);$('#zenCycle').textContent='Sesi '+focus.cycle+' / '+cycles;$('#zenRing').style.setProperty('--zen-progress',pct+'%');$('#zenPlay').textContent=focus.running?'Pause':focus.phase==='focus'?'Lanjut Fokus':'Mulai Istirahat';$('#zenSkip').hidden=focus.phase==='focus';$('#dockClock').textContent=focusTimeText();$('#dockLabel').textContent=focusPhaseLabel()+' • '+(focus.phase==='focus'?(focus.label||cat(focus.category)):'Break')}
function enterFocusMode(native=true){focus.zen=true;updateFocusOverlay();if(native)tryNativeFullscreen()}
function minimizeFocus(){focus.zen=false;updateFocusOverlay();exitNativeFullscreen()}
function phaseMinutes(){return focus.phase==='focus'?focus.work:focus.phase==='longBreak'?focus.long:focus.short}
function syncPomodoro(){focus.work=clamp(+S.settings.pomodoroFocus||25,5,180);focus.short=clamp(+S.settings.pomodoroShortBreak||5,1,60);focus.long=clamp(+S.settings.pomodoroLongBreak||15,1,90);if(!focus.running){focus.total=phaseMinutes()*60;focus.left=focus.total}}

function stats(d=today()){const A=S.activities.filter(x=>x.date===d),T=S.tasks.filter(x=>x.date===d),D=T.filter(x=>x.status==='done'),productive=A.reduce((a,x)=>a+(+x.duration||0),0),completion=T.length?Math.round(D.length/T.length*100):0,focusRatio=clamp(productive/S.profile.dailyFocusTarget,0,1),taskRatio=T.length?D.length/T.length:null,score=Math.round((taskRatio===null?focusRatio:(taskRatio*.5+focusRatio*.5))*100);return{A,T,D,productive,completion,score,xp:A.reduce((a,x)=>a+activityXP(x),0)+D.reduce((a,x)=>a+taskXP(x),0)}}
function streak(){let n=0;for(let i=0;i<365;i++){let s=stats(add(today(),-i));if(s.productive||s.D.length)n++;else break}return n}
function learningActivities(){return S.activities.filter(x=>['study','research','english'].includes(x.category)&&/^\d{2}:\d{2}$/.test(x.startTime||'')&&x.date>=add(today(),-89))}
function studyInsights(){const a=learningActivities(),slots=new Map(),days=new Map();for(const x of a){const h=clamp(parseInt(x.startTime.slice(0,2),10)||0,0,23),start=Math.floor(h/2)*2,key=start;let s=slots.get(key)||{start,sessions:0,minutes:0,completed:0};s.sessions++;s.minutes+=+x.duration||0;s.completed+=x.completed===false?0:1;slots.set(key,s);const wd=new Date(x.date+'T12:00:00').getDay();let d=days.get(wd)||{sessions:0,minutes:0};d.sessions++;d.minutes+=+x.duration||0;days.set(wd,d)}
const ranked=[...slots.values()].map(s=>{s.avg=s.sessions?s.minutes/s.sessions:0;s.completion=s.sessions?s.completed/s.sessions:0;s.score=s.avg*.6+s.completion*25+Math.min(s.sessions,8)/8*20;s.label=String(s.start).padStart(2,'0')+':00–'+String((s.start+2)%24).padStart(2,'0')+':00';return s}).sort((a,b)=>b.score-a.score),best=ranked[0]||null,dayRank=[...days.entries()].map(([day,d])=>({day,...d,avg:d.minutes/d.sessions})).sort((a,b)=>b.avg-a.avg),names=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'],count=a.length,avg=count?a.reduce((z,x)=>z+(+x.duration||0),0)/count:0,confidence=count>=12?'Tinggi':count>=6?'Sedang':'Awal';return{enough:count>=3,count,avg,best,slots:ranked,strongDay:dayRank[0]?names[dayRank[0].day]:'—',confidence}}
function recommendationCard(){const i=studyInsights();if(!i.enough)return'<article class="card recommendation-card" data-widget="recommendation"><div class="card-head"><div><h2>Rekomendasi Waktu Belajar</h2><p>Dihitung otomatis dari histori 90 hari.</p></div><span class="pill orange">Belum cukup data</span></div><div class="empty">Butuh minimal 3 sesi belajar yang memiliki jam mulai. Pomodoro akan mencatat jam ini otomatis; activity manual juga sekarang memiliki field jam mulai.</div></article>';return'<article class="card recommendation-card" data-widget="recommendation"><div class="card-head"><div><h2>Rekomendasi Waktu Belajar</h2><p>Berdasarkan '+i.count+' sesi belajar/riset/English dalam 90 hari.</p></div><span class="pill green">Confidence '+i.confidence+'</span></div><div class="recommend-time">'+i.best.label+'</div><div class="recommend-copy">Di rentang ini rata-rata sesi efektifmu '+mins(i.best.avg)+' dengan '+i.best.sessions+' sesi tercatat. Hari yang paling kuat: <b>'+i.strongDay+'</b>.</div><div class="callout" style="margin-top:12px">Rekomendasi ini mengikuti pola produktivitas historismu, bukan penilaian kemampuan kognitif. Nilainya akan berubah otomatis saat histori bertambah.</div></article>'}
const catMin=(c,days=7)=>S.activities.filter(x=>x.category===c&&x.date>=add(today(),-(days-1))).reduce((a,x)=>a+(+x.duration||0),0);syncPomodoro();
function weeks(off=0){let d=new Date(today()+'T12:00:00'),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day+off*7);return Array.from({length:7},(_,i)=>{let x=new Date(d);x.setDate(d.getDate()+i);return iso(x)})}const weekMin=off=>weeks(off).reduce((a,d)=>a+stats(d).productive,0);
function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;$('#toastWrap').append(e);setTimeout(()=>e.remove(),2400)}
function side(){const l=level();$('#sideLevel').textContent=l.level;$('#sideXP').textContent=num(xp())+' XP';$('#sideXPBar').style.width=l.pct+'%'}
function taskBadgeCount(routeKey){
  const open=S.tasks.filter(t=>t.status!=='done');
  const categoryRoute={study:'study',research:'research',project:'projects',dmath:'dmath',quran:'quran',health:'health',finance:'finance'};
  if(routeKey==='inbox')return open.filter(t=>t.inbox).length;
  if(routeKey==='tasks')return open.filter(t=>!t.inbox).length;
  if(routeKey==='today')return open.filter(t=>!t.inbox&&t.date===today()).length;
  if(routeKey==='calendar')return open.filter(t=>!t.inbox&&t.date===today()).length;if(routeKey==='recovery')return (S.trash?.length||0)+(S.meta.cloudConflict?1:0);
  if(routeKey==='quran'){const taskCount=open.filter(t=>!t.inbox&&t.category==='quran').length,due=(S.quran?.entries||[]).filter(q=>q.nextReview&&q.nextReview<=today()&&q.status!=='new').length;return taskCount+due}
  const category=Object.keys(categoryRoute).find(k=>categoryRoute[k]===routeKey);
  return category?open.filter(t=>!t.inbox&&t.category===category).length:0
}
