function categoryIconSvg(k){
  const routeMap={study:'study',research:'research',project:'projects',dmath:'dmath',quran:'quran',health:'health',finance:'finance',english:'study',personal:'today'};
  return routeIconSvg(routeMap[k]||'today')
}
function badgeHtml(n,cls=''){return n>0?'<span class="nav-badge '+cls+'" aria-label="'+n+' item perlu perhatian">'+(n>99?'99+':n)+'</span>':''}
function nav(){
  $('#sideNav').innerHTML=['CORE','GROWTH','LIFE','INSIGHTS','SYSTEM'].map(g=>'<div class="nav-group"><div class="nav-label">'+g+'</div>'+Object.entries(R).filter(([,v])=>v[2]===g).map(([k,v])=>{const n=taskBadgeCount(k);return'<button class="nav-item '+(route===k?'active':'')+'" data-route="'+k+'" title="'+esc(v[0])+'" aria-label="'+esc(v[0])+'"><span class="nav-icon">'+routeIconSvg(k)+'</span><span class="nav-text">'+v[0]+'</span>'+badgeHtml(n)+'</button>'}).join('')+'</div>').join('');
  $('#bottomNav').innerHTML=[['today','◉','Today'],['life','◫','Life Log'],['tasks','✓','Tasks'],['progress','▤','Progress'],['analytics','•••','More']].map(x=>{const n=taskBadgeCount(x[0]);return'<button class="bottom-item '+(route===x[0]?'active':'')+'" data-route="'+x[0]+'"><span class="bottom-icon-wrap">'+routeIconSvg(x[0])+badgeHtml(n,'bottom-badge')+'</span><span>'+x[2]+'</span></button>'}).join('');
  $('#crumb').textContent=R[route][0]
}
const head=(t,d,a='')=>'<div class="page-head"><div><div class="eyebrow">Desca OS</div><h1>'+esc(t)+'</h1><p>'+esc(d)+'</p></div><div class="page-actions">'+a+'</div></div>',prog=p=>'<div class="progress-track"><span style="width:'+clamp(+p||0,0,100)+'%"></span></div>',metric=(l,v,m,i)=>'<div class="metric-card"><div class="metric-icon">'+i+'</div><div class="metric-label">'+l+'</div><div class="metric-value">'+v+'</div><div class="metric-meta">'+m+'</div></div>';
function goalCard(g){return'<div class="goal-card"><div class="goal-top"><div><div class="goal-title">'+esc(g.title)+'</div><div class="goal-sub">'+esc(g.area)+' • '+fmt(g.deadline,{day:'numeric',month:'short',year:'numeric'})+'</div></div><span class="pill blue">'+g.status+'</span></div><div class="goal-progress">'+prog(g.progress)+'<b>'+g.progress+'%</b></div></div>'}
function focusCard(){let mm=String(Math.floor(focus.left/60)).padStart(2,'0'),ss=String(focus.left%60).padStart(2,'0'),cycles=clamp(+S.settings.pomodoroCycles||4,1,12),phase=focus.phase==='focus'?'FOCUS':focus.phase==='longBreak'?'LONG BREAK':'SHORT BREAK',customLabel=S.settings.pomodoroFocus+' / '+S.settings.pomodoroShortBreak;return'<article class="card focus-card pomodoro-card" data-widget="pomodoro"><div class="card-head"><div><h2>Pomodoro Focus</h2><p>'+phase+' • sesi '+focus.cycle+' / '+cycles+'</p></div><span class="pill">'+(focus.running?'RUNNING':phase)+'</span></div><div class="pomodoro-presets"><button class="pomo-preset '+(S.settings.pomodoroPreset==='classic'?'active':'')+'" data-act="pomoPreset" data-preset="classic" '+(focus.running?'disabled':'')+'>25 / 5</button><button class="pomo-preset '+(S.settings.pomodoroPreset==='deep'?'active':'')+'" data-act="pomoPreset" data-preset="deep" '+(focus.running?'disabled':'')+'>50 / 10</button><button class="pomo-preset '+(S.settings.pomodoroPreset==='custom'?'active':'')+'" data-act="pomoPreset" data-preset="custom" '+(focus.running?'disabled':'')+'>Custom '+(S.settings.pomodoroPreset==='custom'?customLabel:'')+'</button></div><div class="focus-clock" id="focusClock">'+mm+':'+ss+'</div><div class="focus-mode">'+(focus.phase==='focus'?phaseMinutes()+' menit fokus':phaseMinutes()+' menit pemulihan')+'</div>'+(focus.phase==='focus'?'<div class="pomodoro-context"><input id="focusLabel" aria-label="Nama sesi fokus" value="'+esc(focus.label)+'" '+(focus.running?'disabled':'')+'><select id="focusCategory" aria-label="Kategori sesi" '+(focus.running?'disabled':'')+'>'+Object.keys(C).map(x=>'<option value="'+x+'" '+(focus.category===x?'selected':'')+'>'+cat(x)+'</option>').join('')+'</select></div>':'<div class="break-note">Istirahat tidak menambah productive time atau XP. Setelah break selesai, sesi fokus berikutnya siap otomatis.</div>')+'<div class="focus-actions"><button class="btn btn-primary" data-act="focus">'+(focus.running?'Pause':focus.phase==='focus'?'Start Focus':'Start Break')+'</button><button class="btn btn-secondary" data-act="resetFocus">Reset</button>'+(focus.phase!=='focus'?'<button class="btn btn-secondary" data-act="skipBreak">Skip Break</button>':'')+'</div></article>'}
function timeline(d){let a=S.activities.filter(x=>x.date===d).slice(-8).reverse();return a.length?a.map(x=>'<div class="timeline-item"><span>•</span><div class="item-main"><div class="item-title">'+esc(x.title)+'</div><div class="item-meta"><span>'+cat(x.category)+'</span><span>• '+mins(x.duration)+'</span>'+(x.startTime?'<span>• '+x.startTime+'</span>':'')+'<span class="xp-pop">+'+activityXP(x)+' XP</span></div></div></div>').join(''):'<div class="empty">Belum ada aktivitas tercatat.</div>'}
function todayPage(){runAutomationEngine({silent:true});maybeAutoPlanToday();checkReminders();maybeAutoReplan();let t=today(),s=stats(),hr=+new Intl.DateTimeFormat('en-US',{timeZone:S.profile.timezone,hour:'2-digit',hour12:false}).format(new Date()),greet=hr<11?'Selamat pagi':hr<15?'Selamat siang':hr<18?'Selamat sore':'Selamat malam',wk=weekMin(0),pri=S.tasks.filter(x=>x.date===t&&x.status!=='done').sort((a,b)=>priorityRank(b.priority)-priorityRank(a.priority)).slice(0,3),overdue=S.tasks.filter(x=>!x.inbox&&x.status!=='done'&&((x.deadline&&x.deadline<today())||(x.date&&x.date<today()))),mandatory=dueRoutines().filter(r=>r.obligation==='mandatory'&&!routineActivity(r)&&!routineSkip(r)),budgetWarn=S.budgets.filter(b=>b.month===t.slice(0,7)).filter(b=>{const spent=S.finance.filter(x=>x.type==='expense'&&x.date?.startsWith(b.month)&&(x.category||'').toLowerCase()===(b.category||'').toLowerCase()).reduce((n,x)=>n+(+x.amount||0),0);return b.limit&&spent/b.limit>=.8});const attention=[...(overdue.length?[overdue.length+' task overdue']:[]),...(mandatory.length?[mandatory.length+' kegiatan wajib belum selesai']:[]),...(budgetWarn.length?[budgetWarn.length+' budget ≥80%']:[])];$('#page').innerHTML=starterCard()+'<section class="hero-greeting dashboard-hero"><div><div class="eyebrow">'+fmt(t)+'</div><h1>'+greet+', '+esc(S.profile.name)+'.</h1><p>Fokus pada hal penting hari ini. Today diringkas untuk eksekusi; detail task tetap ada di halaman Tasks.</p></div><div class="daily-score"><div class="score-ring" style="--score:'+s.score+'%"><b>'+s.score+'</b></div><div class="score-copy"><b>Daily Score</b><span>'+ (s.score>=70?'Progress yang kuat':'Masih banyak ruang hari ini')+'</span></div></div></section>'+nowNextCard()+(attention.length?'<article class="attention-card"><div><span class="attention-pulse"></span><div><b>Needs Attention</b><p>'+attention.map(esc).join(' • ')+'</p></div></div><button class="btn btn-secondary" data-route="tasks">Review</button></article>':'')+'<section class="grid metric-grid">'+metric('Daily Progress',s.T.length?s.completion+'%':'—',s.T.length?s.D.length+'/'+s.T.length+' task selesai':'Belum ada task hari ini','✓')+metric('Focus Time',mins(s.productive),'Target '+mins(S.profile.dailyFocusTarget),'◷')+metric('XP Today','+'+num(s.xp),'Dari task + activity','✦')+metric('Productive Streak',streak()+' hari','Berdasarkan aktivitas','🔥')+metric('This Week',mins(wk),Math.round(wk/S.profile.weeklyTarget*100)+'% dari target','▤')+'</section>'+summaryCard()+'<section class="grid two-col"><div class="grid">'+smartPlannerCard()+'<article class="card" data-widget="priorities"><div class="card-head"><div><h2>Top Priorities</h2><p>Maksimum tiga hal penting hari ini.</p></div><button class="btn btn-secondary" data-act="addTask">+ Task</button></div><div class="priority-list">'+(pri.length?pri.map(task).join(''):'<div class="empty">Belum ada prioritas aktif hari ini.</div>')+'</div></article>'+todayLifeCard()+dailyTimelineCard()+'</div><div class="grid">'+universalTimerCard()+focusCard()+recommendationCard()+'<article class="card" data-widget="weekly"><div class="card-head"><div><h2>Weekly Target</h2><p>'+mins(wk)+' / '+mins(S.profile.weeklyTarget)+'</p></div><span class="pill blue">'+Math.round(wk/S.profile.weeklyTarget*100)+'%</span></div>'+prog(wk/S.profile.weeklyTarget*100)+'<div class="simple-list" style="margin-top:14px">'+['study','research','project','dmath','quran'].map(k=>'<div class="goal-card"><div class="goal-top"><span class="category-label"><i>'+categoryIconSvg(k)+'</i><span>'+C[k][0]+'</span></span><b>'+mins(catMin(k,7))+'</b></div>'+prog(catMin(k,7)/360*100)+'</div>').join('')+'</div></article><article class="card" data-widget="goals"><div class="card-head"><div><h2>Current Goals</h2><p>Progress dihitung dari milestone + linked task.</p></div><button class="btn btn-ghost" data-route="goals">Semua →</button></div><div class="goal-list">'+(S.goals.length?S.goals.map(goalCard).join(''):'<div class="empty">Belum ada goal aktif.</div>')+'</div></article><article class="note-card" data-widget="note"><div class="card-head"><div><h2>Quick Note</h2><p>Opsional. Untuk capture utama, gunakan Inbox.</p></div></div><textarea id="quickNote" placeholder="Tulis sesuatu..."></textarea><button class="btn btn-primary" data-act="saveNote">Simpan catatan</button></article></div></section>'}
function tasksPage(){let a=S.tasks.filter(x=>!x.inbox);$('#page').innerHTML=head('Tasks','Kelola pekerjaan tanpa kehilangan hubungan dengan goal.', '<button class="btn btn-primary" data-act="addTask">+ Task</button>')+'<section class="grid metric-grid">'+metric('Open',a.filter(x=>x.status!=='done').length,'Belum selesai','○')+metric('Done',a.filter(x=>x.status==='done').length,'Total selesai','✓')+metric('Today',a.filter(x=>x.date===today()).length,'Terjadwal hari ini','◉')+metric('Overdue',a.filter(x=>x.date&&x.date<today()&&x.status!=='done').length,'Perlu perhatian','!')+metric('Inbox',S.tasks.filter(x=>x.inbox).length,'Belum diproses','⌁')+'</section><article class="card"><div class="task-list">'+a.map(task).join('')+'</div></article>'}
function inboxPage(){let a=S.tasks.filter(x=>x.inbox);$('#page').innerHTML=head('Inbox','Tangkap hal yang belum sempat kamu organisasikan.','<button class="btn btn-primary" data-act="addTask">+ Capture</button>')+'<div class="grid two-col"><article class="card"><div class="task-list">'+(a.length?a.map(task).join(''):'<div class="empty">Inbox kosong.</div>')+'</div></article><article class="card"><div class="card-head"><h2>Quick Notes</h2></div><div class="simple-list">'+(S.notes.length?S.notes.slice().reverse().map(n=>'<div class="list-row"><div class="item-main"><div class="item-title">'+esc(n.text)+'</div><div class="item-meta">'+fmt(n.date,{day:'numeric',month:'short'})+'</div></div></div>').join(''):'<div class="empty">Belum ada catatan.</div>')+'</div></article></div>'}
function heat(){let x='';for(let i=139;i>=0;i--){let d=add(today(),-i),m=stats(d).productive,l=!m?'':m<60?'l1':m<150?'l2':m<240?'l3':'l4';x+='<i class="heat-cell '+l+'" title="'+d+' '+mins(m)+'"></i>'}return'<div class="heatmap-wrap"><div class="heatmap">'+x+'</div></div><div class="heat-legend">Less <i class="heat-cell"></i><i class="heat-cell l1"></i><i class="heat-cell l2"></i><i class="heat-cell l3"></i><i class="heat-cell l4"></i> More</div>'}
function lifeHistoryCard(){const a=S.activities.slice().sort((x,y)=>((y.date||'')+(y.startTime||'')).localeCompare((x.date||'')+(x.startTime||''))).slice(0,30);return'<article class="card"><div class="card-head"><div><h2>Recent History</h2><p>30 aktivitas terakhir dari seluruh kategori.</p></div><span class="pill">'+S.activities.length+' total</span></div><div class="life-history">'+(a.length?a.map(x=>'<div class="history-row"><div class="history-date"><b>'+fmt(x.date,{day:'2-digit',month:'short'})+'</b><small>'+esc(x.startTime||'—')+'</small></div><div class="item-main"><div class="item-title">'+esc(x.title)+'</div><div class="item-meta"><span>'+cat(x.category)+'</span><span>'+mins(x.duration)+'</span><span>'+obligationLabel(x.obligation)+'</span><span>'+rhythmLabel(x.rhythm)+'</span><span>'+(x.planned===false?'Spontan':'Planned')+'</span></div></div><span class="xp-pop">+'+activityXP(x)+' XP</span></div>').join(''):'<div class="empty empty-compact">Belum ada histori kegiatan.</div>')+'</div></article>'}
function dailyBaselineCard(){const rows=DAILY_ROUTINE_PRESETS.map(p=>{const current=S.routines.find(r=>r.presetKey===p.presetKey||r.id===p.id);return'<div class="daily-baseline-row"><span class="daily-baseline-icon">'+categoryIconSvg(p.category)+'</span><div><b>'+esc(p.title)+'</b><small>'+esc(p.time)+' • '+mins(p.duration)+' • '+p.days.map(dayName).join(', ')+'</small></div><span class="pill '+(current?.active===false?'':'green')+'">'+(current?.active===false?'OFF':'ACTIVE')+'</span></div>'}).join('');return'<article class="card daily-baseline-card"><div class="card-head"><div><div class="eyebrow">DAILY BASELINE</div><h2>Kegiatan Harian yang Disarankan</h2><p>Baseline otomatis untuk belajar, riset, DMath, olahraga, persiapan S2, dan review. Semua routine tetap bisa diedit.</p></div><button class="mini-btn" data-act="resetDailyBaseline">Reset Baseline</button></div><div class="daily-baseline-list">'+rows+'</div></article>'}
function lifePage(){const d=today(),due=dueRoutines(d),rc=routineCompletion(d),actual=S.activities.filter(a=>a.date===d),adh=routineAdherence(30),mandatoryOpen=due.filter(r=>r.obligation==='mandatory'&&!routineActivity(r,d)&&!routineSkip(r,d)).length,spont=spontaneousActivities(d).length;$('#page').innerHTML=head('Life Log','Fokus pada rutinitas, adherence, dan histori. Planned vs Actual harian ada di Today.','<button class="btn btn-secondary" data-act="newRoutine">+ Routine</button><button class="btn btn-primary" data-act="addActivity">+ Log Activity</button>')+'<section class="grid metric-grid">'+metric('Logged Today',mins(lifeTime(d)),actual.length+' aktivitas','◷')+metric('Routine',rc.due?rc.done+'/'+rc.due:'0','Selesai hari ini','✓')+metric('Wajib Open',mandatoryOpen,'Belum tercatat selesai','!')+metric('Spontaneous',spont,'Non-rutin / unplanned','↯')+metric('30D Adherence',adh.pct+'%','Rutinitas selesai','↗')+'</section><div class="grid life-layout"><div class="grid"><article class="card"><div class="card-head"><div><h2>Rencana Hari Ini</h2><p>Rutinitas dan kewajiban yang jatuh hari ini.</p></div><span class="pill blue">'+rc.pct+'%</span></div><div class="routine-list">'+(due.length?due.map(r=>routineRow(r,d)).join(''):'<div class="empty empty-state-large"><span class="empty-icon">◫</span><b>Belum ada rutinitas.</b><small>Tambahkan kegiatan wajib atau rutin seperti kuliah, belajar, olahraga, ibadah, atau administrasi.</small><button class="btn btn-primary" data-act="newRoutine">Buat Routine</button></div>')+'</div></article>'+lifeHistoryCard()+'</div><aside class="grid">'+dailyBaselineCard()+'<article class="card"><div class="card-head"><div><h2>Routine Templates</h2><p>Jadwal berulang yang otomatis muncul pada harinya.</p></div><button class="mini-btn" data-act="newRoutine">+ Add</button></div><div class="routine-template-list">'+(S.routines.length?S.routines.map(r=>'<div class="routine-template '+(r.active===false?'inactive':'')+'"><div class="item-main"><div class="item-title">'+esc(r.title)+'</div><div class="item-meta"><span>'+cat(r.category)+'</span><span>'+esc(r.time||'Fleksibel')+'</span><span>'+r.days.map(Number).sort((a,b)=>a-b).map(dayName).join(', ')+'</span></div></div><button class="mini-btn" data-act="editRoutine" data-id="'+r.id+'">Edit</button><button class="switch '+(r.active===false?'':'on')+'" data-act="toggleRoutine" data-id="'+r.id+'" aria-label="Aktif/nonaktif routine"></button></div>').join(''):'<div class="empty empty-compact">Belum ada template.</div>')+'</div></article><article class="card"><div class="card-head"><h2>Coverage 30 Hari</h2></div><div class="coverage-score">'+adh.pct+'%</div>'+prog(adh.pct)+'<div class="simple-list coverage-list"><div class="list-row"><div class="item-main"><div class="item-title">Semua routine</div><div class="item-meta">'+adh.done+' dari '+adh.due+' occurrence selesai</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Kegiatan wajib</div><div class="item-meta">'+adh.mandatoryPct+'% completion</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Spontan hari ini</div><div class="item-meta">'+spont+' kegiatan non-rutin</div></div></div></div></article></aside></div>'}
function progressPage(){let l=level();$('#page').innerHTML=head('Progress','Konsistensi, level, skill, heatmap, dan milestone dalam satu halaman.')+'<section class="grid metric-grid">'+metric('XP',num(xp()),'Task + activity','✦')+metric('Level',l.level,'Current level','↑')+metric('Streak',streak()+' hari','Current streak','🔥')+metric('Active Days',new Set(S.activities.map(x=>x.date)).size,'Hari tercatat','▦')+metric('Sessions',S.activities.length,'Activity logs','○')+'</section><div class="grid two-col"><article class="card"><div class="card-head"><div><h2>Activity Heatmap</h2><p>140 hari terakhir.</p></div></div>'+heat()+'</article><article class="card"><div class="card-head"><div><h2>Level Progress</h2><p>'+l.cur+' / 1200 XP</p></div></div><div class="metric-value">Level '+l.level+'</div>'+prog(l.pct)+'<div class="callout" style="margin-top:14px">XP adalah feedback konsistensi dari task dan activity, bukan ukuran nilai dirimu.</div></article></div><article class="card section-gap"><div class="card-head"><h2>Skill Progress</h2></div><div class="grid three-col">'+['study','research','project','dmath','quran','health'].map(k=>{let m=catMin(k,90),lv=Math.floor(m/600)+1;return'<div class="goal-card"><div class="goal-title">'+C[k][0]+'</div><div class="goal-sub">Level '+lv+' • '+mins(m)+'</div><div class="goal-progress">'+prog((m%600)/6)+'<b>'+Math.round((m%600)/6)+'%</b></div></div>'}).join('')+'</div></article>'+achievementSection()}
const S2_PIPELINE=[
['research','Researching'],
['preparing','Preparing'],
['ready','Ready'],
['applied','Applied'],
['interview','Interview / Selection'],
['accepted','Accepted'],
['rejected','Rejected']
];
function s2StageLabel(v){return S2_PIPELINE.find(x=>x[0]===v)?.[1]||v||'Researching'}
function s2TargetProgress(v){if(v==='rejected')return 100;const i=S2_PIPELINE.findIndex(x=>x[0]===v);return i<0?0:clamp(Math.round(i/(S2_PIPELINE.length-2)*100),0,100)}
function s2TargetCollection(type){return type==='scholarship'?S.s2Prep.scholarships:S.s2Prep.universities}
function s2TargetForm(type,x={}){
  const label=type==='scholarship'?'Beasiswa':'Kampus / Program';
  return'<form id="s2TargetForm"><div class="form-grid"><div class="field full"><label>'+label+'</label><input name="name" required autofocus value="'+esc(x.name||'')+'"></div><div class="field full"><label>Program / fokus</label><input name="program" value="'+esc(x.program||'')+'" placeholder="Contoh: S2 Matematika · Analisis"></div><div class="field"><label>Status</label><select name="status">'+S2_PIPELINE.map(v=>'<option value="'+v[0]+'" '+((x.status||'research')===v[0]?'selected':'')+'>'+v[1]+'</option>').join('')+'</select></div><div class="field"><label>Deadline</label><input name="deadline" type="date" value="'+esc(x.deadline||'')+'"></div><div class="field"><label>Tanggal daftar</label><input name="appliedDate" type="date" value="'+esc(x.appliedDate||'')+'"></div><div class="field full"><label>Link</label><input name="url" type="url" value="'+esc(x.url||'')+'" placeholder="Opsional"></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="4">'+esc(x.notes||'')+'</textarea></div></div><input type="hidden" name="type" value="'+type+'"><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary smart-submit">Simpan '+label+'</button></form>'
}
function openS2Target(type,x=null){open('<div class="modal-head"><div><div class="eyebrow">S2 APPLICATION PIPELINE</div><h2 id="modalTitle">'+(x?'Edit ':'Tambah ')+(type==='scholarship'?'Beasiswa':'Kampus / Program')+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+s2TargetForm(type,x||{}))}
function s2TargetCard(type,x){
  const pct=s2TargetProgress(x.status),deadline=x.deadline?fmt(x.deadline,{day:'numeric',month:'short',year:'numeric'}):'Belum ada deadline';
  return'<article class="s2-pipeline-card"><div class="s2-pipeline-top"><div><span class="pill '+s2StatusPill(x.status)+'">'+esc(s2StageLabel(x.status))+'</span><h4>'+esc(x.name)+'</h4><small>'+esc(x.program||'Program belum diisi')+'</small></div><button class="mini-btn" data-act="editS2Target" data-target-type="'+type+'" data-id="'+x.id+'">Edit</button></div>'+prog(pct)+'<div class="s2-pipeline-meta"><span>Deadline</span><b>'+esc(deadline)+'</b>'+(x.appliedDate?'<span>Daftar</span><b>'+esc(fmt(x.appliedDate,{day:'numeric',month:'short',year:'numeric'}))+'</b>':'')+'</div>'+(x.notes?'<p>'+esc(x.notes.slice(0,150))+'</p>':'')+'</article>'
}
function s2PipelineSection(){
  const universities=S.s2Prep.universities||[],scholarships=S.s2Prep.scholarships||[],all=[...universities,...scholarships],upcoming=all.filter(x=>x.deadline&&x.status!=='accepted'&&x.status!=='rejected').sort((a,b)=>a.deadline.localeCompare(b.deadline))[0];
  return'<section class="s2-pipeline-section"><div class="s2-documents-head"><div><div class="eyebrow">APPLICATION PIPELINE</div><h3>Rencana Daftar</h3><p>Lacak kampus dan beasiswa dari tahap riset sampai hasil akhir.</p></div><div class="s2-doc-actions">'+(upcoming?'<span class="pill orange">Next '+fmt(upcoming.deadline,{day:'numeric',month:'short'})+'</span>':'')+'<button class="mini-btn" data-act="newS2University">+ Kampus</button><button class="mini-btn" data-act="newS2Scholarship">+ Beasiswa</button></div></div><div class="s2-pipeline-columns"><div><div class="s2-section-title"><b>Kampus / Program</b><span>'+universities.length+'</span></div><div class="s2-pipeline-list">'+(universities.length?universities.map(x=>s2TargetCard('university',x)).join(''):'<div class="empty empty-compact">Belum ada target kampus.</div>')+'</div></div><div><div class="s2-section-title"><b>Beasiswa</b><span>'+scholarships.length+'</span></div><div class="s2-pipeline-list">'+(scholarships.length?scholarships.map(x=>s2TargetCard('scholarship',x)).join(''):'<div class="empty empty-compact">Belum ada target beasiswa.</div>')+'</div></div></div></section>'
}
function s2StatusPill(status){return status==='applied'||status==='interview'?'orange':status==='accepted'?'green':status==='ready'||status==='preparing'||status==='shortlist'?'blue':status==='rejected'?'red':''}
function s2DocumentSection(){const docs=S.s2Prep?.documents||[],groups=[...new Set(docs.map(x=>x.group||'Lainnya'))],pr=s2DocumentProgress();return'<section class="s2-documents"><div class="s2-documents-head"><div><div class="eyebrow">DOCUMENT CHECKLIST</div><h3>Berkas yang Disiapkan</h3><p>Checklist dasar agar berkas inti sudah siap lebih awal. Persyaratan final tetap mengikuti kampus dan beasiswa tujuan.</p></div><div class="s2-doc-actions"><span class="pill blue">'+pr.done+'/'+pr.total+' siap</span><button class="mini-btn" data-act="syncS2DocumentTasks">↻ Sync Berkas</button><button class="mini-btn" data-act="newS2Document">+ Berkas</button></div></div>'+prog(pr.pct)+'<div class="s2-document-grid">'+groups.map(g=>'<div class="s2-document-group"><div class="s2-section-title"><b>'+esc(g)+'</b><span>'+docs.filter(x=>(x.group||'Lainnya')===g&&s2DocumentDone(x)).length+'/'+docs.filter(x=>(x.group||'Lainnya')===g).length+'</span></div>'+docs.filter(x=>(x.group||'Lainnya')===g).map(x=>'<button class="s2-doc-row '+(s2DocumentDone(x)?'done':'')+'" data-act="toggleS2Document" data-id="'+x.id+'"><span class="s2-doc-check">'+(s2DocumentDone(x)?'✓':'')+'</span><div><b>'+esc(x.title)+'</b><small>'+(x.due?'Target '+fmt(x.due,{day:'numeric',month:'short',year:'numeric'}):'Belum diberi target tanggal')+(x.taskId?' • linked task':'')+'</small></div></button>').join('')+'</div>').join('')+'</div></section>'}
function s2PrepCard(){
  const p=S.s2Prep||seed().s2Prep,pr=s2Progress(),docPr=s2DocumentProgress(),next=s2NextItem(),groups=[...new Set((p.checklist||[]).map(x=>x.group||'General'))];
  return'<article class="card s2-prep-card"><div class="card-head"><div><div class="eyebrow">MASTER\'S PREPARATION</div><h2>Persiapan Kuliah S2</h2><p>Pipeline kampus dan beasiswa, kesiapan dokumen, tes, riset, serta task berada dalam satu alur.</p></div><div class="button-row"><button class="mini-btn" data-act="syncS2Tasks">↻ Sync Persiapan</button><button class="mini-btn" data-act="newS2Item">+ Checklist</button><button class="mini-btn" data-act="editS2Prep">Edit Fokus</button></div></div><div class="s2-overview"><div class="s2-readiness"><strong>'+pr.pct+'%</strong><span>overall readiness</span>'+prog(pr.pct)+'<small>'+pr.done+' dari '+pr.total+' item siap</small></div><div class="s2-profile"><span>Fokus</span><b>'+esc(p.focus||'Belum ditentukan')+'</b><span>Target intake</span><b>'+esc(p.targetIntake||'Belum ditentukan')+'</b></div><div class="s2-next"><span>Next step</span><b>'+esc(next?.title||'Semua checklist selesai')+'</b><small>'+(next?.due?'Target '+fmt(next.due,{day:'numeric',month:'short',year:'numeric'}):'Belum ada target tanggal')+'</small></div></div><div class="s2-readiness-strip"><div><span>Berkas siap</span><b>'+docPr.pct+'%</b></div><div><span>Checklist total</span><b>'+pr.done+'/'+pr.total+'</b></div><div><span>Beasiswa dipantau</span><b>'+p.scholarships.length+'</b></div><div><span>Kampus target</span><b>'+p.universities.length+'</b></div></div>'+s2PipelineSection()+s2DocumentSection()+'<section class="s2-strategy-section"><div class="s2-documents-head"><div><div class="eyebrow">PREPARATION CHECKLIST</div><h3>Persiapan Umum</h3><p>Hal-hal yang perlu disiapkan di luar pipeline pendaftaran.</p></div></div><div class="s2-checklist">'+groups.map(g=>'<div class="s2-check-group"><div class="s2-section-title"><b>'+esc(g)+'</b><span>'+p.checklist.filter(x=>(x.group||'General')===g&&s2ItemDone(x)).length+'/'+p.checklist.filter(x=>(x.group||'General')===g).length+'</span></div>'+p.checklist.filter(x=>(x.group||'General')===g).map(x=>'<button class="s2-check '+(s2ItemDone(x)?'done':'')+'" data-act="toggleS2Item" data-id="'+x.id+'"><span>'+(s2ItemDone(x)?'✓':'○')+'</span><div><b>'+esc(x.title)+'</b><small>'+(x.due?fmt(x.due,{day:'numeric',month:'short',year:'numeric'}):'Tanpa target tanggal')+(x.taskId?' • linked task':'')+'</small></div></button>').join('')+'</div>').join('')+'</div></section>'+(p.notes?'<div class="callout" style="margin-top:14px">'+esc(p.notes)+'</div>':'')+'</article>'
}
function s2Lines(items=[]){return items.map(x=>x.name+' | '+(x.status||'research')).join('\n')}
function s2ParseLines(raw,prefix){return String(raw||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map((line,i)=>{const parts=line.split('|').map(v=>v.trim());return{id:prefix+'_'+i+'_'+Date.now().toString(36),name:parts[0],status:parts[1]||'research',program:'',deadline:'',appliedDate:'',url:'',notes:''}})}
function s2PrepForm(){const p=S.s2Prep;return'<form id="s2PrepForm"><div class="form-grid"><div class="field"><label>Fokus bidang</label><input name="focus" value="'+esc(p.focus||'')+'" placeholder="Analisis / Kombinatorika"></div><div class="field"><label>Target intake</label><input name="targetIntake" value="'+esc(p.targetIntake||'')+'" placeholder="Contoh 2027 / 2028"></div><div class="field full"><label>Catatan umum</label><textarea name="notes" rows="4">'+esc(p.notes||'')+'</textarea></div></div><div class="callout" style="margin-top:12px">Kampus dan beasiswa sekarang dikelola lewat Application Pipeline agar deadline dan status tidak hilang.</div><button class="btn btn-primary" style="margin-top:14px;width:100%">Simpan Fokus S2</button></form>'}
function openS2Prep(){open('<div class="modal-head"><div><div class="eyebrow">GOALS · S2</div><h2 id="modalTitle">Persiapan Kuliah S2</h2></div><button class="icon-btn" data-act="close">×</button></div>'+s2PrepForm())}
function s2ItemForm(){return'<form id="s2ItemForm"><div class="form-grid"><div class="field full"><label>Persiapan</label><input name="title" required placeholder="Contoh: Minta surat rekomendasi"></div><div class="field"><label>Kelompok</label><select name="group">'+['Academic','Documents','Research','Tests','Scholarship','Application','General'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>Target tanggal</label><input name="due" type="date" value="'+today()+'"></div></div><button class="btn btn-primary" style="margin-top:14px;width:100%">Tambah Checklist</button></form>'}
function s2DocumentForm(){return'<form id="s2DocumentForm"><div class="form-grid"><div class="field full"><label>Nama berkas</label><input name="title" required placeholder="Contoh: Sertifikat TOEFL"></div><div class="field"><label>Kelompok</label><select name="group">'+['Identitas','Akademik','Aplikasi','Riset','Rekomendasi','Bahasa','Beasiswa','Lainnya'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>Target tanggal</label><input name="due" type="date" value="'+today()+'"></div></div><button class="btn btn-primary" style="margin-top:14px;width:100%">Tambah Berkas</button></form>'}
function openS2Document(){open('<div class="modal-head"><div><div class="eyebrow">S2 DOCUMENTS</div><h2 id="modalTitle">Tambah Berkas</h2></div><button class="icon-btn" data-act="close">×</button></div>'+s2DocumentForm())}
function syncS2DocumentTasks(){let made=0;for(const item of (S.s2Prep.documents||[]).filter(x=>!s2DocumentDone(x))){if(item.taskId&&S.tasks.some(t=>t.id===item.taskId))continue;const id=uid('t');S.tasks.push({id,title:'Berkas S2 · '+item.title,date:item.due||today(),deadline:item.due||'',status:'planned',priority:'medium',category:'study',goalId:null,projectId:null,studyTopicId:null,estimate:30,startTime:'',notes:'Dibuat otomatis dari checklist berkas Persiapan S2',inbox:false,subtasks:[],tags:['s2','documents'],recurrence:'none',dependsOn:null,googleTaskSync:false,googleCalendarSync:false,googleTaskId:null,googleTaskListId:null,googleCalendarEventId:null,googleOrigin:false,recurringSpawned:false});item.taskId=id;made++}save('Sync S2 documents to tasks');toast(made?made+' task berkas S2 dibuat':'Berkas S2 sudah tersinkron');render()}
function openS2Item(){open('<div class="modal-head"><div><div class="eyebrow">S2 CHECKLIST</div><h2 id="modalTitle">Tambah Persiapan</h2></div><button class="icon-btn" data-act="close">×</button></div>'+s2ItemForm())}
function syncS2Tasks(){let made=0;for(const item of S.s2Prep.checklist.filter(x=>!s2ItemDone(x))){if(item.taskId&&S.tasks.some(t=>t.id===item.taskId))continue;const id=uid('t');S.tasks.push({id,title:'S2 · '+item.title,date:item.due||today(),deadline:item.due||'',status:'planned',priority:'medium',category:'study',goalId:null,projectId:null,studyTopicId:null,estimate:60,startTime:'',notes:'Dibuat otomatis dari Persiapan S2',inbox:false,subtasks:[],tags:['s2','preparation'],recurrence:'none',dependsOn:null,googleTaskSync:false,googleCalendarSync:false,googleTaskId:null,googleTaskListId:null,googleCalendarEventId:null,googleOrigin:false,recurringSpawned:false});item.taskId=id;made++}save('Sync S2 checklist to tasks');toast(made?made+' task S2 dibuat otomatis':'Checklist S2 sudah tersinkron');render()}
function goalsPage(){refreshGoalProgress();const active=S.goals.filter(g=>g.status!=='completed').length,avg=S.goals.length?Math.round(S.goals.reduce((a,g)=>a+goalComputedProgress(g),0)/S.goals.length):0;$('#page').innerHTML=head('Goals','Goal → milestone → task → activity. Progress bisa dihitung otomatis dari pekerjaan nyata.','<button class="btn btn-primary" data-act="newGoal">+ Goal</button>')+'<section class="grid metric-grid compact-metrics">'+metric('Active Goals',active,'Sedang berjalan','◎')+metric('Avg Progress',avg+'%','Semua goal','↗')+metric('Completed',S.goals.filter(g=>g.status==='completed').length,'Goal selesai','✓')+metric('Linked Tasks',S.tasks.filter(t=>t.goalId).length,'Task terhubung','▦')+metric('Linked Activity',S.activities.filter(a=>a.goalId).length,'Aktivitas terhubung','✦')+'</section>'+s2PrepCard()+'<div class="grid goals-layout"><div class="grid">'+(S.goals.length?S.goals.map(g=>{const gp=goalComputedProgress(g),linked=S.tasks.filter(t=>t.goalId===g.id),md=g.milestoneDone||[];return'<article class="card goal-detail"><div class="card-head"><div><div class="goal-status-row"><span class="pill '+(g.status==='completed'?'green':g.status==='paused'?'orange':'blue')+'">'+(g.status||'active')+'</span><span class="goal-deadline">'+fmt(g.deadline,{day:'numeric',month:'short',year:'numeric'})+'</span><span class="pill">'+(g.autoProgress===false?'MANUAL':'AUTO')+'</span></div><h2>'+esc(g.title)+'</h2><p>'+esc(g.area||'Goal')+' • '+linked.filter(t=>t.status==='done').length+'/'+linked.length+' linked task selesai</p></div><button class="mini-btn" data-act="editGoal" data-id="'+g.id+'">Edit</button></div><div class="goal-progress hero-progress">'+prog(gp)+'<b>'+gp+'%</b></div><div class="simple-list milestone-list" style="margin-top:14px">'+((g.milestones||[]).length?(g.milestones||[]).map((m,i)=>'<button class="list-row milestone-toggle '+(md.includes(i)?'done':'')+'" data-act="toggleMilestone" data-id="'+g.id+'" data-index="'+i+'"><span class="milestone-check">'+(md.includes(i)?'✓':'○')+'</span><div class="item-title">'+esc(m)+'</div></button>').join(''):'<div class="empty empty-compact">Belum ada milestone.</div>')+'</div>'+(linked.length?'<div class="goal-linked-tasks"><div class="item-meta" style="margin:14px 0 8px">LINKED TASKS</div>'+linked.slice(0,6).map(task).join('')+'</div>':'')+'</article>'}).join(''):'<div class="empty empty-state-large"><span class="empty-icon">◎</span><b>Belum ada goal.</b><small>Buat satu tujuan yang benar-benar ingin kamu dorong bulan ini.</small><button class="btn btn-primary" data-act="newGoal">Buat Goal Pertama</button></div>')+'</div><aside class="card goal-guide"><div class="card-head"><div><h2>Goal → Action</h2><p>Progress mengikuti pekerjaan nyata.</p></div></div><div class="goal-flow"><span>Goal</span><i>→</i><span>Milestone</span><i>→</i><span>Task</span><i>→</i><span>Activity</span><i>→</i><span>Review</span></div><div class="callout" style="margin-top:16px">Mode Auto menghitung rata-rata completion milestone dan linked task. Jika belum ada keduanya, progress manual tetap dipakai.</div></aside></div>'}
function chartEmpty(msg='Belum ada data untuk grafik ini.'){return'<div class="chart-empty"><span>▥</span><b>Belum cukup data</b><small>'+esc(msg)+'</small></div>'}
function lineChart(values,labels,{suffix='m',height=176}={}){if(!values.some(v=>+v>0))return chartEmpty();const w=640,h=height,p=24,max=Math.max(...values,1),step=(w-p*2)/Math.max(values.length-1,1),pts=values.map((v,i)=>[p+i*step,h-p-(+v/max)*(h-p*2)]),poly=pts.map(x=>x.join(',')).join(' '),area=p+','+(h-p)+' '+poly+' '+(w-p)+','+(h-p),ticks=[0,.25,.5,.75,1].map(q=>'<line x1="'+p+'" y1="'+(h-p-q*(h-p*2))+'" x2="'+(w-p)+'" y2="'+(h-p-q*(h-p*2))+'" class="chart-gridline"/>').join(''),dots=pts.map((pt,i)=>'<circle cx="'+pt[0]+'" cy="'+pt[1]+'" r="3.2" class="chart-dot"><title>'+esc(labels[i]||'')+': '+Math.round(values[i])+' '+suffix+'</title></circle>').join(''),showEvery=Math.max(1,Math.ceil(labels.length/7)),xlabels=labels.map((l,i)=>i%showEvery===0||i===labels.length-1?'<text x="'+pts[i][0]+'" y="'+(h-5)+'" text-anchor="middle" class="chart-xlabel">'+esc(l)+'</text>':'').join('');return'<div class="svg-chart"><svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Grafik tren">'+ticks+'<polygon points="'+area+'" class="chart-area"/><polyline points="'+poly+'" class="chart-line"/>'+dots+xlabels+'</svg></div>'}
function trendSeries(days=14,category=null){const dates=Array.from({length:days},(_,i)=>add(today(),-(days-1-i))),values=dates.map(d=>category?S.activities.filter(x=>x.date===d&&x.category===category).reduce((a,x)=>a+(+x.duration||0),0):stats(d).productive),labels=dates.map(d=>fmt(d,{day:'numeric',month:'short'}));return{dates,values,labels}}
function categoryBars(days=30){const start=add(today(),-(days-1)),rows=Object.keys(C).map(k=>({k,label:cat(k),value:S.activities.filter(a=>a.date>=start&&a.category===k).reduce((n,a)=>n+(+a.duration||0),0)})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value),max=Math.max(...rows.map(x=>x.value),1);return rows.length?'<div class="category-chart">'+rows.map(x=>'<div class="category-chart-row"><span>'+esc(x.label)+'</span><div class="category-chart-track"><i style="width:'+clamp(x.value/max*100,0,100)+'%"></i></div><b>'+mins(x.value)+'</b></div>').join('')+'</div>':chartEmpty()}
function monthKeyOffset(off){const d=new Date(today()+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+off);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
