function plannedActualChart(days=14){const ds=Array.from({length:days},(_,i)=>add(today(),-(days-1-i))),planned=ds.map(d=>S.activities.filter(a=>a.date===d&&a.planned!==false).reduce((n,a)=>n+(+a.duration||0),0)),spont=ds.map(d=>S.activities.filter(a=>a.date===d&&a.planned===false).reduce((n,a)=>n+(+a.duration||0),0)),max=Math.max(...planned,...spont,1);if(!planned.some(Boolean)&&!spont.some(Boolean))return chartEmpty();return'<div class="stack-chart">'+ds.map((d,i)=>{const total=planned[i]+spont[i],ph=planned[i]/max*120,sh=spont[i]/max*120;return'<div class="stack-col" title="'+fmt(d,{day:'numeric',month:'short'})+' • Planned '+mins(planned[i])+' • Spontan '+mins(spont[i])+'"><div class="stack-bars"><i class="planned" style="height:'+ph+'px"></i><i class="spontaneous" style="height:'+sh+'px"></i></div><span>'+fmt(d,{weekday:'narrow'})+'</span></div>'}).join('')+'</div><div class="chart-legend"><span><i class="planned"></i> Planned</span><span><i class="spontaneous"></i> Spontan</span></div>'}
