function journalPage(){let j=S.journal[today()]||{};$('#page').innerHTML=head('Journal','Tutup hari dengan refleksi singkat.')+'<div class="grid two-col"><article class="card"><div class="card-head"><div><h2>Daily Reflection</h2><p>'+fmt(today())+'</p></div></div><div class="form-grid"><div class="field full"><label>Apa yang berhasil diselesaikan?</label><textarea id="ja">'+esc(j.a||'')+'</textarea></div><div class="field full"><label>Apa yang dipelajari?</label><textarea id="jl">'+esc(j.l||'')+'</textarea></div><div class="field full"><label>Apa yang bisa diperbaiki?</label><textarea id="ji">'+esc(j.i||'')+'</textarea></div><div class="field full"><label>Prioritas besok</label><textarea id="jt">'+esc(j.t||'')+'</textarea></div></div><button class="btn btn-primary" data-act="saveJournal">Simpan refleksi</button></article><article class="card"><div class="card-head"><h2>Recent Entries</h2></div><div class="simple-list">'+(Object.entries(S.journal).slice(-10).reverse().map(([d,x])=>'<div class="list-row"><div><b>'+fmt(d,{weekday:'short',day:'numeric',month:'short'})+'</b><div class="item-meta">'+esc((x.l||x.a||'').slice(0,80))+'</div></div></div>').join('')||'<div class="empty">Belum ada entry.</div>')+'</div></article></div>'}
function analyticsPage(){let w=weekMin(0),p=weekMin(-1),delta=p?Math.round((w-p)/p*100):(w?100:0),i=studyInsights(),pomos=S.activities.filter(x=>x.source==='pomodoro'&&x.completed!==false&&x.date>=add(today(),-29)).length,adh=routineAdherence(30),a30=S.activities.filter(a=>a.date>=add(today(),-29)),unplanned=a30.filter(a=>a.planned===false),unplannedMin=unplanned.reduce((n,a)=>n+(+a.duration||0),0),tr=trendSeries(30);$('#page').innerHTML=head('Analytics','Insight utama saja—tanpa grafik yang menyampaikan informasi yang sama dua kali.')+'<section class="grid metric-grid">'+metric('This Week',mins(w),(delta>=0?'▲ ':'▼ ')+Math.abs(delta)+'% vs lalu','▤')+metric('Routine Adherence',adh.pct+'%',adh.done+'/'+adh.due+' occurrence 30D','✓')+metric('Unplanned Time',mins(unplannedMin),unplanned.length+' kegiatan 30D','↯')+metric('Best Study Window',i.enough?i.best.label:'Belum cukup data',i.enough?'Confidence '+i.confidence:i.count+'/3 sesi minimum','★')+metric('Pomodoro 30D',pomos,'Sesi selesai','⏱')+'</section><article class="card chart-card"><div class="card-head"><div><h2>30-Day Productive Time</h2><p>Tren total aktivitas produktif harian.</p></div><span class="pill blue">'+mins(tr.values.reduce((n,v)=>n+v,0))+'</span></div>'+lineChart(tr.values,tr.labels,{suffix:'menit',height:190})+'</article><div class="grid two-col section-gap"><article class="card"><div class="card-head"><div><h2>Activity Distribution</h2><p>Waktu 30 hari berdasarkan kategori.</p></div></div>'+categoryBars(30)+'</article><article class="card"><div class="card-head"><div><h2>Plan vs Spontaneous</h2><p>14 hari terakhir.</p></div></div>'+plannedActualChart(14)+'</article></div><div class="grid two-col section-gap"><article class="card"><div class="card-head"><div><h2>Life Log Quality</h2><p>Kualitas pencatatan dan rutinitas 30 hari.</p></div></div><div class="simple-list"><div class="list-row"><div class="item-main"><div class="item-title">Routine adherence</div><div class="item-meta">'+adh.pct+'% semua routine • '+adh.mandatoryPct+'% kegiatan wajib</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Spontaneous activity</div><div class="item-meta">'+unplanned.length+' kegiatan • '+mins(unplannedMin)+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Total activities</div><div class="item-meta">'+a30.length+' log dalam 30 hari</div></div></div></div></article>'+recommendationCard()+'</div>'}
function reviewPage(){let w=weekMin(0),p=weekMin(-1),days=weeks(),activeDays=days.filter(d=>S.activities.some(a=>a.date===d)||S.tasks.some(t=>t.date===d&&t.status==='done')).length,pomo=days.reduce((n,d)=>n+S.activities.filter(x=>x.date===d&&x.source==='pomodoro'&&x.completed!==false).length,0),tasks=days.flatMap(d=>S.tasks.filter(t=>t.date===d)),done=tasks.filter(t=>t.status==='done'),comp=tasks.length?Math.round(done.length/tasks.length*100):0,adh=routineAdherence(7),cats=Object.keys(C).map(k=>[k,days.reduce((n,d)=>n+S.activities.filter(a=>a.date===d&&a.category===k).reduce((s,a)=>s+(+a.duration||0),0),0)]).sort((a,b)=>b[1]-a[1]),top=cats[0],month=today().slice(0,7),expense=S.finance.filter(x=>x.type==='expense'&&x.date?.startsWith(month)).reduce((n,x)=>n+(+x.amount||0),0),health=S.healthLogs.filter(x=>days.includes(x.date)),sleep=health.length?health.reduce((n,x)=>n+(+x.sleep||0),0)/health.length:0,over=S.tasks.filter(t=>t.status!=='done'&&t.deadline&&t.deadline<today()).length,delta=p?Math.round((w-p)/p*100):0;const wins=[comp>=70?'Task completion '+comp+'%':null,adh.pct>=70?'Routine adherence '+adh.pct+'%':null,w>p&&p?'Productive time naik '+Math.abs(delta)+'%':null].filter(Boolean),watch=[over?over+' deadline lewat':null,comp<50&&tasks.length?'Task completion baru '+comp+'%':null,sleep&&sleep<7?'Rata-rata tidur '+sleep.toFixed(1)+' jam':null].filter(Boolean);$('#page').innerHTML=head('Reviews','Weekly review otomatis dari aktivitas, task, routine, health, goal, dan finance.')+'<article class="card review-hero"><div class="grid two-col"><div><div class="eyebrow" style="color:#7EDBFF">WEEKLY REVIEW</div><div class="review-number">'+mins(w)+'</div><div class="muted">'+(p?(delta>=0?'+':'')+delta+'% vs minggu lalu':'Baseline pertama')+'</div></div><div class="stat-strip"><div class="stat-chip"><b>'+done.length+'/'+tasks.length+'</b><span>tasks completed</span></div><div class="stat-chip"><b>'+adh.pct+'%</b><span>routine adherence</span></div><div class="stat-chip"><b>'+pomo+'</b><span>Pomodoro</span></div><div class="stat-chip"><b>'+activeDays+'/7</b><span>active days</span></div></div></div></article><div class="grid two-col section-gap"><article class="card"><div class="card-head"><h2>Yang Membaik</h2></div>'+(wins.length?'<div class="review-insight-list">'+wins.map(x=>'<div class="review-insight positive">↗ '+esc(x)+'</div>').join('')+'</div>':'<div class="empty">Belum ada sinyal peningkatan yang cukup kuat minggu ini.</div>')+'</article><article class="card"><div class="card-head"><h2>Perlu Perhatian</h2></div>'+(watch.length?'<div class="review-insight-list">'+watch.map(x=>'<div class="review-insight warning">! '+esc(x)+'</div>').join('')+'</div>':'<div class="empty">Tidak ada warning utama dari data minggu ini.</div>')+'</article></div><div class="grid two-col section-gap"><article class="card"><div class="card-head"><h2>Weekly Summary</h2></div><div class="simple-list"><div class="list-row"><div class="item-main"><div class="item-title">Kategori dominan</div><div class="item-meta">'+(top&&top[1]?cat(top[0])+' • '+mins(top[1]):'Belum ada data')+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Pengeluaran bulan berjalan</div><div class="item-meta">'+money(expense)+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Rata-rata tidur</div><div class="item-meta">'+(sleep?sleep.toFixed(1)+' jam':'Belum ada health log')+'</div></div></div></div></article>'+recommendationCard()+'</div><article class="card section-gap"><div class="card-head"><div><h2>Goal Check</h2><p>Progress otomatis dari milestone + linked task.</p></div></div><div class="goal-list">'+(S.goals.length?S.goals.map(goalCard).join(''):'<div class="empty">Belum ada goal.</div>')+'</div></article>'}
function achievementData(){return[['🌱','The Beginning','Catat aktivitas pertama',S.activities.length>0],['🔥','Consistent','Streak produktif 7 hari',streak()>=7],['⚡','Unstoppable','Streak produktif 30 hari',streak()>=30],['📚','Scholar','50 sesi belajar',S.activities.filter(x=>x.category==='study').length>=50],['⏱','Pomodoro Habit','25 Pomodoro selesai',S.activities.filter(x=>x.source==='pomodoro'&&x.completed!==false).length>=25],['🧠','Deep Thinker','10.000 XP otomatis',xp()>=10000],['📑','Researcher','30 sesi riset',S.activities.filter(x=>x.category==='research').length>=30],['🏃','Runner','20 sesi lari',S.runs.length>=20],['✦','Level Up','Level 10',level().level>=10]]}
