function calendarEventDetail(kind,id,d){if(kind==='quranreview'){const q=S.quran.entries.find(x=>x.id===id);if(!q)return;open('<div class="modal-head"><div><div class="eyebrow">MURAJAAH</div><h2 id="modalTitle">'+quranLabel(q)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>Q</span><div><b>'+fmt(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+clamp(+q.mastery||0,0,100)+'% mastery • '+quranVerseCount(q)+' ayat</small></div></div>'+(q.notes?'<div class="event-notes">'+esc(q.notes)+'</div>':'')+'<div class="event-actions"><button class="btn btn-primary" data-act="reviewQuranEntry" data-id="'+q.id+'">Catat Murajaah</button><button class="btn btn-secondary" data-act="editQuranEntry" data-id="'+q.id+'">Edit Hafalan</button></div></div>');return}if(kind==='dmathcontent'){const x=S.dmath.content.find(v=>v.id===id);if(!x)return;open('<div class="modal-head"><div><div class="eyebrow">DMATH CONTENT</div><h2 id="modalTitle">'+esc(x.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>D</span><div><b>'+fmt(x.scheduledDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+esc(S.dmath[x.platform]?.name||x.platform)+' • '+esc(x.format||'Content')+' • '+dmathContentStatusLabel(x.status)+'</small></div></div>'+(x.notes?'<div class="event-notes">'+esc(x.notes)+'</div>':'')+'<div class="event-actions"><button class="btn btn-primary" data-act="editDMathContent" data-id="'+x.id+'">Edit Content</button></div></div>');return}if(kind==='google'){const e=S.googleEvents.find(x=>x.id===id);if(!e)return;open('<div class="modal-head"><div><div class="eyebrow">GOOGLE CALENDAR</div><h2 id="modalTitle">'+esc(e.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>G</span><div><b>'+fmt(e.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+(e.allDay?'All-day':(esc(e.time||'—')+(e.duration?' • '+mins(e.duration):'')))+'</small></div></div>'+(e.description?'<div class="event-notes">'+esc(e.description)+'</div>':'')+'<div class="event-actions"><button class="btn btn-primary" data-act="importGoogleEvent" data-id="'+e.id+'">Import sebagai Task</button>'+(e.htmlLink?'<button class="btn btn-secondary" data-act="openExternal" data-url="'+esc(e.htmlLink)+'">Buka Google Calendar</button>':'')+'</div></div>');return}if(kind==='task'){const t=S.tasks.find(x=>x.id===id);if(!t)return;const done=t.status==='done',earned=taskXP(t);open('<div class="modal-head"><div><div class="eyebrow">CALENDAR EVENT</div><h2 id="modalTitle">'+esc(t.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>▦</span><div><b>'+fmt(t.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+(t.startTime?esc(t.startTime)+' • ':'')+mins(t.estimate||0)+'</small></div></div><div class="event-detail-grid"><div><span>Kategori</span><b>'+cat(t.category)+'</b></div><div><span>Prioritas</span><b>'+esc(t.priority||'medium')+'</b></div><div><span>Goal</span><b>'+esc(goal(t.goalId)||'—')+'</b></div><div><span>Status</span><b>'+(done?'Selesai':'Belum selesai')+'</b></div></div>'+(t.notes?'<div class="event-notes">'+esc(t.notes)+'</div>':'')+'<div class="event-xp">+'+earned+' XP ketika selesai</div><div class="event-actions">'+(!done?'<button class="btn btn-primary" data-act="completeCalendar" data-kind="task" data-id="'+t.id+'" data-date="'+d+'">✓ Tandai Selesai</button>':'<span class="event-completed">✓ Sudah selesai • +'+earned+' XP</span>')+'<button class="btn btn-secondary" data-act="editTask" data-id="'+t.id+'">Edit</button></div></div>');return}const r=S.routines.find(x=>x.id===id);if(!r)return;const a=routineActivity(r,d),done=!!a,earned=a?activityXP(a):activityXP({duration:r.duration,category:r.category,source:'routine',obligation:r.obligation,goalId:r.goalId});open('<div class="modal-head"><div><div class="eyebrow">ROUTINE EVENT</div><h2 id="modalTitle">'+esc(r.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>↻</span><div><b>'+fmt(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+(r.time?esc(r.time)+' • ':'')+mins(r.duration||0)+'</small></div></div><div class="event-detail-grid"><div><span>Kategori</span><b>'+cat(r.category)+'</b></div><div><span>Sifat</span><b>'+obligationLabel(r.obligation)+'</b></div><div><span>Goal</span><b>'+esc(goal(r.goalId)||'—')+'</b></div><div><span>Status</span><b>'+(done?'Selesai':routineSkip(r,d)?'Dilewati':'Belum selesai')+'</b></div></div><div class="event-xp">+'+earned+' XP ketika selesai</div><div class="event-actions">'+(!done&&!routineSkip(r,d)?'<button class="btn btn-primary" data-act="completeCalendar" data-kind="routine" data-id="'+r.id+'" data-date="'+d+'">✓ Tandai Selesai</button>':done?'<span class="event-completed">✓ Sudah selesai • +'+earned+' XP</span>':'<span class="pill">Dilewati</span>')+'<button class="btn btn-secondary" data-act="editRoutine" data-id="'+r.id+'">Edit Routine</button></div></div>')}
function completeCalendar(kind,id,d){close();if(kind==='task'){const t=S.tasks.find(x=>x.id===id);if(t&&t.status!=='done'){t.status='done';spawnRecurringTask(t);refreshGoalProgress();save();if(googleReady()&&(t.googleTaskSync||t.googleCalendarSync))syncTaskGoogle(t);toast(t.title+' selesai · +'+taskXP(t)+' XP');render()}}else completeRoutine(id,d)}
