function normalizeDoi(raw=''){return String(raw||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').replace(/^doi:\s*/i,'').trim()}
function crossrefDoiPath(doi){return normalizeDoi(doi).split('/').map(x=>encodeURIComponent(x)).join('/')}
async function importPaperMetadata(){
  const form=$('#researchPaperForm');if(!form)return;
  const raw=form.elements.doi?.value||form.elements.url?.value||'',doi=normalizeDoi(raw);
  if(!doi){toast('Masukkan DOI atau link doi.org');return}
  const btn=form.querySelector('[data-act="importPaperMeta"]');if(btn){btn.disabled=true;btn.textContent='Mengambil...'}
  try{
    const res=await fetch('https://api.crossref.org/v1/works/'+crossrefDoiPath(doi));
    if(!res.ok)throw new Error('Metadata DOI tidak ditemukan');
    const json=await res.json(),m=json?.message||{},title=(m.title||[])[0]||'',authors=(m.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean).join(', '),year=String(m.published?.['date-parts']?.[0]?.[0]||m.issued?.['date-parts']?.[0]?.[0]||''),url=m.URL||('https://doi.org/'+doi),tags=(m.subject||[]).slice(0,6).join(', ');
    if(form.elements.title&&title)form.elements.title.value=title;
    if(form.elements.authors&&authors)form.elements.authors.value=authors;
    if(form.elements.year&&year)form.elements.year.value=year;
    if(form.elements.doi)form.elements.doi.value=doi;
    if(form.elements.url)form.elements.url.value=url;
    if(form.elements.tags&&tags)form.elements.tags.value=tags;
    const projectId=inferProjectId(title||form.elements.title?.value||'','__auto__');if(projectId&&form.elements.projectId)form.elements.projectId.value=projectId;
    toast('Metadata paper berhasil diambil')
  }catch(err){toast('Import DOI gagal: '+(err?.message||err))}
  finally{if(btn){btn.disabled=false;btn.textContent='Ambil Metadata'}}
}
