function routineForm(r={}){const days=(r.days||[1,2,3,4,5]).map(Number);return'<form id="routineForm"><div class="form-grid"><div class="field full"><label>Nama kegiatan rutin</label><input name="title" required value="'+esc(r.title||'')+'" placeholder="Contoh: Kuliah, olahraga, belajar malam"></div><div class="field"><label>Jam</label><input name="time" type="time" value="'+esc(r.time||'07:00')+'"></div><div class="field"><label>Durasi (menit)</label><input name="duration" type="number" min="1" value="'+(r.duration||60)+'"></div><div class="field"><label>Kategori</label><select name="category">'+Object.keys(C).map(x=>'<option value="'+x+'" '+((r.category||'personal')===x?'selected':'')+'>'+cat(x)+'</option>').join('')+'</select></div><div class="field"><label>Sifat</label><select name="obligation"><option value="mandatory" '+(r.obligation==='mandatory'?'selected':'')+'>Wajib</option><option value="important" '+((r.obligation||'important')==='important'?'selected':'')+'>Penting</option><option value="optional" '+(r.obligation==='optional'?'selected':'')+'>Opsional</option></select></div><div class="field full"><label>Hari aktif</label><div class="day-picker">'+['Min','Sen','Sel','Rab','Kam','Jum','Sab'].map((n,i)=>'<label class="day-check"><input type="checkbox" name="days" value="'+i+'" '+(days.includes(i)?'checked':'')+'><span>'+n+'</span></label>').join('')+'</div></div><div class="field full"><label>Linked Goal</label><select name="goalId"><option value="">Tanpa goal</option>'+S.goals.map(g=>'<option value="'+g.id+'" '+(r.goalId===g.id?'selected':'')+'>'+esc(g.title)+'</option>').join('')+'</select></div></div><input type="hidden" name="id" value="'+(r.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Routine</button></form>'}
